/* DAWAH X — ahmad, অধ্যায় 113 · খণ্ড 113 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][113]=[[22401,22401,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏حُيَيُّ بْنُ عَبْدِ اللَّهِ الْمَعَافِرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ الْحُبُلِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا فِي ‏ ‏الْبَحْرِ وَعَلَيْنَا ‏ ‏عَبْدُ اللَّهِ بْنُ قَيْسٍ الْفَزَارِيُّ ‏ ‏وَمَعَنَا ‏ ‏أَبُو أَيُّوبَ الْأَنْصَارِيُّ ‏ ‏فَمَرَّ بِصَاحِبِ الْمَقَاسِمِ وَقَدْ أَقَامَ ‏ ‏السَّبْيَ ‏ ‏فَإِذَا امْرَأَةٌ تَبْكِي فَقَالَ مَا شَأْنُ هَذِهِ قَالُوا فَرَّقُوا بَيْنَهَا وَبَيْنَ وَلَدِهَا قَالَ فَأَخَذَ بِيَدِ وَلَدِهَا حَتَّى وَضَعَهُ فِي يَدِهَا فَانْطَلَقَ صَاحِبُ الْمَقَاسِمِ إِلَى ‏ ‏عَبْدِ اللَّهِ بْنِ قَيْسٍ ‏ ‏فَأَخْبَرَهُ فَأَرْسَلَ إِلَى ‏ ‏أَبِي أَيُّوبَ ‏ ‏فَقَالَ مَا حَمَلَكَ عَلَى مَا صَنَعْتَ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ فَرَّقَ بَيْنَ وَالِدَةٍ وَوَلَدِهَا فَرَّقَ اللَّهُ بَيْنَهُ وَبَيْنَ الْأَحِبَّةِ يَوْمَ الْقِيَامَةِ ‏","","",""],[22402,22402,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَبْدِ رَبِّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ جَابِرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ أَخِي أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏يَذْكُرُ عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّهَا سَتُفْتَحُ عَلَيْكُمْ ‏ ‏الْأَمْصَارُ ‏ ‏وَسَيَضْرِبُونَ عَلَيْكُمْ بُعُوثًا يُنْكِرُ الرَّجُلُ مِنْكُمْ الْبَعْثَ فَيَتَخَلَّصُ مِنْ قَوْمِهِ وَيَعْرِضُ نَفْسَهُ عَلَى الْقَبَائِلِ يَقُولُ مَنْ ‏ ‏أَكْفِيهِ بَعْثَ كَذَا وَكَذَا أَلَا وَذَلِكَ الْأَجِيرُ إِلَى آخِرِ قَطْرَةٍ مِنْ دَمِهِ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ هُو ابْنُ بَرِّيٍّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ حَرْبٍ الْخَوْلَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ سُلَيْمَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ جَابِرٍ الطَّائِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ أَخِي أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏أَنَّهُ ‏ ‏كَتَبَ إِلَيْهِ ‏ ‏أَبُو أَيُّوبَ ‏ ‏يُخْبِرُهُ أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَهُ ‏","","",""],[22403,22403,"","","‏ ‏حَدَّثَنَا ‏ ‏الْمُقْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ بْنُ شُرَيْحٍ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏حَدَّثَنِي ‏ ‏بَحِيرُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو رُهْمٍ السَّمَعِيُّ ‏ ‏أَنَّ ‏ ‏أَبَا أَيُّوبَ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ جَاءَ يَعْبُدُ اللَّهَ لَا يُشْرِكُ بِهِ شَيْئًا وَيُقِيمُ الصَّلَاةَ ‏ ‏وَيُؤْتِي الزَّكَاةَ وَيَصُومُ رَمَضَانَ وَيَجْتَنِبُ الْكَبَائِرَ فَإِنَّ لَهُ الْجَنَّةَ وَسَأَلُوهُ مَا الْكَبَائِرُ قَالَ الْإِشْرَاكُ بِاللَّهِ وَقَتْلُ النَّفْسِ الْمُسْلِمَةِ وَفِرَارٌ يَوِمَ الزَّحْفِ ‏","","",""],[22404,22404,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏ضَمْضَمِ بْنِ زُرْعَةَ ‏ ‏عَنْ ‏ ‏شُرَيْحِ بْنِ عُبَيْدٍ ‏ ‏أَنَّ ‏ ‏أَبَا رُهْمٍ السَّمَعِيَّ ‏ ‏كَانَ يُحَدِّثُ أَنَّ ‏ ‏أَبَا أَيُّوبَ الْأَنْصَارِيَّ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏إِنَّ كُلَّ صَلَاةٍ تَحُطُّ مَا بَيْنَ يَدَيْهَا مِنْ خَطِيئَةٍ ‏","","",""],[22405,22405,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ هُبَيْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ الْحُبُلِيِّ ‏ ‏أَنَّ ‏ ‏أَبَا أَيُّوبَ الْأَنْصَارِيَّ ‏ ‏قَالَ ‏ ‏أُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِقَصْعَةٍ ‏ ‏فِيهَا بَصَلٌ فَقَالَ ‏ ‏كُلُوا وَأَبَى أَنْ يَأْكُلَ وَقَالَ إِنِّي لَسْتُ كَمِثْلِكُمْ ‏","","",""],[22406,22406,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو قَبِيلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ نَاشِرٍ ‏ ‏مِنْ ‏ ‏بَنِي سَرِيعٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا رُهْمٍ ‏ ‏قَاصَّ ‏ ‏أَهْلِ ‏ ‏الشَّامِ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَبَا أَيُّوبَ الْأَنْصَارِيَّ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ ذَاتَ يَوْمٍ إِلَيْهِمْ فَقَالَ لَهُمْ ‏ ‏إِنَّ رَبَّكُمْ عَزَّ وَجَلَّ خَيَّرَنِي بَيْنَ سَبْعِينَ أَلْفًا يَدْخَلُونَ الْجَنَّةَ بِغَيْرِ حِسَابٍ وَبَيْنَ ‏ ‏الْخَبِيئَةِ ‏ ‏عِنْدَهُ لِأُمَّتِي فَقَالَ لَهُ بَعْضُ أَصْحَابِهِ يَا رَسُولَ اللَّهِ أَيُخَبِّئُ ذَلِكَ رَبُّكَ عَزَّ وَجَلَّ فَدَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ خَرَجَ وَهُوَ يُكَبِّرُ فَقَالَ إِنَّ رَبِّي عَزَّ وَجَلَّ زَادَنِي مَعَ كُلِّ أَلْفٍ سَبْعِينَ أَلْفًا ‏ ‏وَالْخَبِيئَةُ ‏ ‏عِنْدَهُ قَالَ ‏ ‏أَبُو رُهْمٍ ‏ ‏يَا ‏ ‏أَبَا أَيُّوبَ ‏ ‏وَمَا تَظُنُّ ‏ ‏خَبِيئَةَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَكَلَهُ النَّاسُ بِأَفْوَاهِهِمْ فَقَالُوا وَمَا أَنْتَ وَخَبِيئَةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَبُو أَيُّوبَ ‏ ‏دَعُوا الرَّجُلَ عَنْكُمْ أُخْبِرْكُمْ عَنْ خَبِيئَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَمَا أَظُنُّ بَلْ كَالْمُسْتَيْقِنِ إِنَّ خَبِيئَةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَقُولَ رَبِّ مَنْ شَهِدَ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ مُصَدِّقًا لِسَانَهُ قَلْبُهُ أَدْخِلْهُ ‏ ‏الْجَنَّةَ ‏","","",""],[22407,22407,"","","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏أَخْبَرَنَا ‏ ‏بَقِيَّةُ ‏ ‏عَنْ ‏ ‏بَحِيرٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏أَنَّ ‏ ‏أَبَا رُهْمٍ السَّمَعِيَّ ‏ ‏حَدَّثَهُمْ عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ عَبَدَ اللَّهَ لَا يُشْرِكُ بِهِ شَيْئًا وَأَقَامَ الصَّلَاةَ وَآتَى الزَّكَاةَ وَصَامَ رَمَضَانَ وَاجْتَنَبَ الْكَبَائِرَ فَلَهُ ‏ ‏الْجَنَّةُ ‏ ‏أَوْ دَخَلَ الْجَنَّةَ ‏ ‏فَسَأَلَهُ مَا الْكَبَائِرُ فَقَالَ الشِّرْكُ بِاللَّهِ وَقَتْلُ نَفْسٍ مُسْلِمَةٍ وَالْفِرَارُ يَوْمَ الزَّحْفِ ‏","","",""],[22408,22408,"","","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏أَخْبَرَنَا ‏ ‏بَقِيَّةُ ‏ ‏عَنْ ‏ ‏بَحِيرِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏قَالَ ‏ ‏لَمَّا قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏اقْتَرَعَتْ ‏ ‏الْأَنْصَارُ ‏ ‏أَيُّهُمْ ‏ ‏يُؤْوِي رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَرَعَهُمْ ‏ ‏أَبُو أَيُّوبَ ‏ ‏فَآوَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكَانَ إِذَا أُهْدِيَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَعَامٌ أُهْدِيَ ‏ ‏لِأَبِي أَيُّوبَ ‏ ‏قَالَ فَدَخَلَ ‏ ‏أَبُو أَيُّوبَ ‏ ‏يَوْمًا فَإِذَا ‏ ‏قَصْعَةٌ ‏ ‏فِيهَا بَصَلٌ فَقَالَ مَا هَذَا فَقَالُوا أَرْسَلَ بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَاطَّلَعَ ‏ ‏أَبُو أَيُّوبَ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ مَا مَنَعَكَ مِنْ هَذِهِ ‏ ‏الْقَصْعَةِ ‏ ‏قَالَ رَأَيْتُ فِيهَا بَصَلًا قَالَ وَلَا يَحِلُّ لَنَا الْبَصَلُ قَالَ بَلَى ‏ ‏فَكُلُوهُ وَلَكِنْ ‏ ‏يَغْشَانِي مَا لَا ‏ ‏يَغْشَاكُمْ ‏ ‏وَقَالَ ‏ ‏حَيْوَةُ ‏ ‏إِنَّهُ ‏ ‏يَغْشَانِي مَا لَا ‏ ‏يَغْشَاكُمْ ‏","","",""],[22409,22409,"","","‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ بْنُ شُرَيْحٍ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏حَدَّثَنِي ‏ ‏بَحِيرُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كِيلُوا طَعَامَكُمْ يُبَارَكْ لَكُمْ فِيهِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْجَبَّارِ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏عَنْ ‏ ‏بَحِيرٍ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[22410,22410,"","","‏ ‏حَدَّثَنَا ‏ ‏هَيْثَمٌ يَعْنِي ابْنَ خَارِجَةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏بَحِيرِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كِيلُوا طَعَامَكُمْ يُبَارَكْ لَكُمْ فِيهِ ‏","","",""],[22411,22411,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي جَعْفَرٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏قَالَ ‏ ‏وَحَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي جَعْفَرٍ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏عَمْرِو بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدُ اللَّهِ مَعَ الْقَاضِي حِينَ يَقْضِي وَيَدُ اللَّهِ مَعَ الْقَاسِمِ حِينَ يَقْسِمُ ‏","","",""],[22412,22412,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏حَدَّثَنَا ‏ ‏رِشْدِينُ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏بُكَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَهُمْ ‏ ‏أَنَّهُمْ ذَكَرُوا يَوْمًا مَا ‏ ‏يُنْتَبَذُ ‏ ‏فِيهِ فَتَنَازَعُوا فِي الْقَرْعِ فَمَرَّ بِهِمْ ‏ ‏أَبُو أَيُّوبَ الْأَنْصَارِيُّ ‏ ‏فَأَرْسَلُوا إِلَيْهِ إِنْسَانًا فَقَالَ يَا ‏ ‏أَبَا أَيُّوبَ ‏ ‏الْقَرْعُ ‏ ‏يُنْتَبَذُ ‏ ‏فِيهِ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى عَنْ كُلِّ ‏ ‏مُزَفَّتٍ ‏ ‏يُنْتَبَذُ ‏ ‏فِيهِ فَرَدَّ عَلَيْهِ الْقَرْعَ فَرَدَّ ‏ ‏أَبَا أَيُّوبَ ‏ ‏مِثْلَ قَوْلِهِ الْأَوَّلِ ‏","","",""],[22413,22413,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏رِشْدِينُ ‏ ‏حَدَّثَنِي ‏ ‏حُيَيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏رَجُلٌ مِنْ ‏ ‏يَحْصَبَ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ الْحُبُلِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ فَرَّقَ بَيْنَ الْوَلَدِ وَوَالِدِهِ فِي الْبَيْعِ فَرَّقَ اللَّهُ عَزَّ وَجَلَّ بَيْنَهُ وَبَيْنَ أَحِبَّتِهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[22414,22414,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ إِسْحَاقَ ‏ ‏مَوْلَى ‏ ‏أَبِي طَلْحَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا أَيُّوبَ الْأَنْصَارِيَّ ‏ ‏يَقُولُ وَهُوَ ‏ ‏بِمِصْرَ ‏ ‏وَاللَّهِ مَا أَدْرِي كَيْفَ أَصْنَعُ بِهَذِهِ ‏ ‏الْكَرَابِيسِ ‏ ‏يَعْنِي ‏ ‏الْكُنُفَ ‏ ‏وَقَدْ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ذَهَبَ أَحَدُكُمْ إِلَى الْغَائِطِ ‏ ‏أَوْ الْبَوْلِ ‏ ‏فَلَا يَسْتَقْبِلْ الْقِبْلَةَ وَلَا يَسْتَدْبِرْهَا ‏","","",""],[22415,22415,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنِي ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ قَيْسٍ ‏ ‏قَاصُّ ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَبِي صِرْمَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏أَنَّهُ ‏ ‏قَالَ حِينَ حَضَرَتْهُ الْوَفَاةُ قَدْ كُنْتُ كَتَمْتُ عَنْكُمْ شَيْئًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَوْلَا أَنَّكُمْ تُذْنِبُونَ لَخَلَقَ اللَّهُ تَبَارَكَ وَتَعَالَى قَوْمًا يُذْنِبُونَ فَيَغْفِرُ لَهُمْ ‏","","",""],[22416,22416,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ الْمَدَائِنِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏عَبَّادُ بْنُ الْعَوَّامِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ إِيَاسٍ ‏ ‏عَنْ ‏ ‏أَبِي الْوَرْدِ ‏ ‏عَنْ ‏ ‏أَبِي مُحَمَّدٍ الْحَضْرَمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏لَمَّا قَدِمَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏نَزَلَ عَلَيَّ فَقَالَ لِي يَا ‏ ‏أَبَا أَيُّوبَ ‏ ‏أَلَا أُعَلِّمُكَ قَالَ قُلْتُ بَلَى يَا رَسُولَ اللَّهِ قَالَ ‏ ‏مَا مِنْ عَبْدٍ يَقُولُ حِينَ يُصْبِحُ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ إِلَّا كَتَبَ اللَّهُ لَهُ بِهَا عَشْرَ حَسَنَاتٍ وَمَحَا عَنْهُ عَشْرَ سَيِّئَاتٍ وَإِلَّا كُنَّ لَهُ عِنْدَ اللَّهِ عَدْلَ عَشْرِ رِقَابٍ مُحَرَّرِينَ وَإِلَّا كَانَ فِي جُنَّةٍ مِنْ الشَّيْطَانِ حَتَّى يُمْسِيَ وَلَا قَالَهَا حِينَ يُمْسِي إِلَّا كَذَلِكَ ‏ ‏قَالَ ‏ ‏فَقُلْتُ ‏ ‏لِأَبِي مُحَمَّدٍ ‏ ‏أَنْتَ سَمِعْتَهَا مِنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏قَالَ ‏ ‏آللَّهِ لَسَمِعْتُهُ مِنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏يُحَدِّثُهُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[22417,22417,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ يَعْنِي أَبَا زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أَفْلَحَ ‏ ‏مَوْلَى ‏ ‏أَبِي أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَزَلَ عَلَيْهِ فَنَزَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْفَلَ ‏ ‏وَأَبُو أَيُّوبَ ‏ ‏فِي الْعُلُوِّ فَانْتَبَهَ ‏ ‏أَبُو أَيُّوبَ ‏ ‏ذَاتَ لَيْلَةٍ فَقَالَ نَمْشِي فَوْقَ رَأْسِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَحَوَّلَ فَبَاتُوا فِي جَانِبٍ فَلَمَّا أَصْبَحَ ذَكَرَ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏السُّفْلُ أَرْفَقُ بِي فَقَالَ ‏ ‏أَبُو أَيُّوبَ ‏ ‏لَا ‏ ‏أَعْلُو ‏ ‏سَقِيفَةً ‏ ‏أَنْتَ تَحْتَهَا فَتَحَوَّلَ ‏ ‏أَبُو أَيُّوبَ ‏ ‏فِي السُّفْلِ وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْعُلُوِّ فَكَانَ يَصْنَعُ طَعَامَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَبْعَثُ إِلَيْهِ فَإِذَا رُدَّ إِلَيْهِ سَأَلَ عَنْ مَوْضِعِ أَصَابِعِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَتَّبِعُ أَثَرَ أَصَابِعِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَأْكُلُ مِنْ حَيْثُ أَثَرِ أَصَابِعِهِ فَصَنَعَ ذَاتَ يَوْمٍ طَعَامًا فِيهِ ثُومٌ فَأَرْسَلَ بِهِ إِلَيْهِ فَسَأَلَ عَنْ مَوْضِعِ أَثَرِ أَصَابِعِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقِيلَ لَمْ يَأْكُلْ فَصَعِدَ إِلَيْهِ فَقَالَ أَحَرَامٌ هُوَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكْرَهُهُ قَالَ فَإِنِّي أَكْرَهُ مَا تَكْرَهُ ‏ ‏أَوْ مَا كَرِهْتَهُ ‏ ‏وَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُؤْتَى ‏","","",""],[22418,22418,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ إِبْرَاهِيمَ الرَّازِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سَلَمَةُ بْنُ الْفَضْلِ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ يَزِيدَ بْنِ جَابِرٍ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُخَيْمِرَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَعِيشَ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَالَ إِذَا صَلَّى الصُّبْحَ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ عَشْرَ مَرَّاتٍ كُنَّ كَعَدْلِ أَرْبَعِ رِقَابٍ وَكُتِبَ لَهُ بِهِنَّ عَشْرُ حَسَنَاتٍ وَمُحِيَ عَنْهُ بِهِنَّ عَشْرُ سَيِّئَاتٍ وَرُفِعَ لَهُ بِهِنَّ عَشْرُ دَرَجَاتٍ وَكُنَّ لَهُ حَرَسًا مِنْ الشَّيْطَانِ حَتَّى يُمْسِيَ وَإِذَا قَالَهَا بَعْدَ الْمَغْرِبِ فَمِثْلُ ذَلِكَ ‏","","",""],[22419,22419,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَاقُ ‏ ‏ابْنُ أَخِي ‏ ‏أَنَسٍ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏أَنَّهُ ‏ ‏قَالَ مَا نَدْرِي كَيْفَ نَصْنَعُ ‏ ‏بِكَرَابِيسِ ‏ ‏مِصْرَ ‏ ‏وَقَدْ ‏ ‏نَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ نَسْتَقْبِلَ الْقِبْلَتَيْنِ وَنَسْتَدْبِرَهُمَا ‏ ‏و قَالَ ‏ ‏هَمَّامٌ ‏ ‏يَعْنِي ‏ ‏الْغَائِطَ وَالْبَوْلَ ‏","","",""],[22420,22420,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ يَعْنِي الْخُرَاسَانِيَّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ الْعَزِيزِ اللَّيْثِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ شِهَابٍ ‏ ‏يَقُولُ أَشْهَدُ عَلَى ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏أَنَّهُ حَدَّثَهُ عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَا مِنْ رَجُلٍ يَغْرِسُ غَرْسًا إِلَّا كَتَبَ اللَّهُ عَزَّ وَجَلَّ لَهُ مِنْ الْأَجْرِ قَدْرَ مَا يَخْرُجُ مِنْ ثَمَرِ ذَلِكَ ‏ ‏الْغَرْسِ ‏","","",""],[22421,22421,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَسْلَمَ أَبِي عِمْرَانَ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏بَادِرُوا بِصَلَاةِ الْمَغْرِبِ قَبْلَ طُلُوعِ النَّجْمِ ‏","","",""],[22422,22422,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏رَاشِدٍ الْيَافِعِيِّ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَوْسٍ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏أَنَّهُ قَالَ ‏ ‏كُنَّا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا فَقَرَّبَ طَعَامًا فَلَمْ أَرَ طَعَامًا كَانَ أَعْظَمَ بَرَكَةً مِنْهُ أَوَّلَ مَا أَكَلْنَا وَلَا أَقَلَّ بَرَكَةً فِي آخِرِهِ قُلْنَا كَيْفَ هَذَا يَا رَسُولَ اللَّهِ قَالَ ‏ ‏لِأَنَّا ذَكَرْنَا اسْمَ اللَّهِ عَزَّ وَجَلَّ حِينَ أَكَلْنَا ثُمَّ قَعَدَ بَعْدُ مَنْ ‏ ‏أَكَلَ وَلَمْ يُسَمِّ فَأَكَلَ مَعَهُ الشَّيْطَانُ ‏","","",""],[22423,22423,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ أَهْلِ ‏ ‏مَكَّةَ ‏ ‏أَنَّ ‏ ‏يَزِيدَ بْنَ مُعَاوِيَةَ ‏ ‏كَانَ أَمِيرًا عَلَى الْجَيْشِ الَّذِي غَزَا فِيهِ ‏ ‏أَبُو أَيُّوبَ ‏ ‏فَدَخَلَ عَلَيْهِ عِنْدَ الْمَوْتِ فَقَالَ لَهُ ‏ ‏أَبُو أَيُّوبَ ‏ ‏إِذَا مِتُّ فَاقْرَءُوا عَلَى النَّاسِ مِنِّي السَّلَامَ فَأَخْبِرُوهُمْ أَنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ مَاتَ لَا يُشْرِكُ بِاللَّهِ شَيْئًا جَعَلَهُ اللَّهُ فِي الْجَنَّةِ وَلْيَنْطَلِقُوا بِي فَلْيَبْعُدُوا بِي فِي أَرْضِ ‏ ‏الرُّومِ ‏ ‏مَا اسْتَطَاعُوا ‏ ‏فَحَدَّثَ النَّاسُ لَمَّا مَاتَ ‏ ‏أَبُو أَيُّوبَ ‏ ‏فَاسْتَلْأَمَ النَّاسُ وَانْطَلَقُوا بِجِنَازَتِهِ ‏","","",""],[22424,22424,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ أَمْلَى عَلَيَّ ‏ ‏مَعْمَرُ بْنُ رَاشِدٍ ‏ ‏أَخْبَرَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَتَى أَحَدُكُمْ الْغَائِطَ فَلَا يَسْتَقْبِلَنَّ الْقِبْلَةَ وَلَكِنْ لِيُشَرِّقْ أَوْ لِيُغَرِّبْ ‏ ‏قَالَ ‏ ‏فَلَمَّا قَدِمْنَا ‏ ‏الشَّامَ ‏ ‏وَجَدْنَا مَرَاحِيضَ جُعِلَتْ نَحْوَ الْقِبْلَةِ فَنَنْحَرِفُ وَنَسْتَغْفِرُ اللَّهَ ‏","","",""],[22425,22425,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ سَمُرَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أُتِيَ بِطَعَامٍ أَكَلَ مِنْهُ وَبَعَثَ بِفَضْلِهِ إِلَيَّ وَإِنَّهُ بَعَثَ يَوْمًا ‏ ‏بِقَصْعَةٍ ‏ ‏لَمْ يَأْكُلْ مِنْهَا شَيْئًا فِيهَا ثُومٌ فَسَأَلْتُهُ أَحَرَامٌ هُوَ قَالَ ‏ ‏لَا وَلَكِنِّي أَكْرَهُهُ مِنْ أَجْلِ رِيحِهِ قَالَ فَإِنِّي أَكْرَهُ مَا كَرِهْتَ ‏","","",""],[22426,22426,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏وَاصِلٌ الرَّقَاشِيُّ ‏ ‏عَنْ ‏ ‏أَبِي سَوْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا أُتِيَ بِطَعَامٍ نَالَ مِنْهُ مَا شَاءَ اللَّهُ أَنْ يَنَالَ ثُمَّ يَبْعَثُ بِسَائِرِهِ إِلَى ‏ ‏أَبِي أَيُّوبَ ‏ ‏وَفِيهِ أَثَرُ يَدِهِ فَأُتِيَ بِطَعَامٍ فِيهِ الثُّومُ فَلَمْ يَطْعَمْ مِنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَيْئًا وَبَعَثَ بِهِ إِلَى ‏ ‏أَبِي أَيُّوبَ ‏ ‏فَقَالَ لَهُ أَهْلُهُ فَقَالَ ادْنُوهُ مِنِّي فَإِنِّي أَحْتَاجُ إِلَيْهِ فَلَمَّا لَمْ يَرَ أَثَرَ يَدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِ كَفَّ يَدَهُ مِنْهُ وَأَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا نَبِيَّ اللَّهِ بِأَبِي وَأُمِّي هَذَا الطَّعَامُ لَمْ تَأْكُلْ مِنْهُ آكُلُ مِنْهُ قَالَ ‏ ‏فِيهِ تِلْكَ الثُّومَةُ فَيَسْتَأْذِنُ عَلَيَّ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏قَالَ فَآكُلُ مِنْهُ يَا رَسُولَ اللَّهِ قَالَ نَعَمْ فَكُلْ ‏","","",""],[22427,22427,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏وَاصِلٍ الرَّقَاشِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَوْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏و عَنْ ‏ ‏عَطَاءٍ ‏ ‏قَالَا ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَبَّذَا ‏ ‏الْمُتَخَلِّلُونَ ‏ ‏قِيلَ وَمَا ‏ ‏الْمُتَخَلِّلُونَ ‏ ‏قَالَ فِي الْوُضُوءِ وَالطَّعَامِ ‏","","",""],[22428,22428,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏يَذْكُرُ فِيهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلَاثٍ يَلْتَقِيَانِ فَيَصُدُّ هَذَا وَيَصُدُّ هَذَا وَخَيْرُهُمَا الَّذِي يَبْدَأُ بِالسَّلَامِ ‏","","",""],[22429,22429,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ اللَّهِ بْنِ حُنَيْنٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏اخْتَلَفَ ‏ ‏الْمِسْوَرُ ‏ ‏وَابْنُ عَبَّاسٍ ‏ ‏وَقَالَ ‏ ‏مَرَّةً ‏ ‏امْتَرَى ‏ ‏فِي الْمُحْرِمِ يَصُبُّ عَلَى رَأْسِهِ الْمَاءَ قَالَ فَأَرْسَلُوا إِلَى ‏ ‏أَبِي أَيُّوبَ ‏ ‏كَيْفَ رَأَيْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَغْسِلُ رَأْسَهُ فَقَالَ هَكَذَا مُقْبِلًا وَمُدْبِرًا ‏ ‏وَصَفَهُ ‏ ‏سُفْيَانُ ‏","","",""],[22430,22430,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ بَشِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَفْضَلَ ‏ ‏الصَّدَقَةِ ‏ ‏الصَّدَقَةُ ‏ ‏عَلَى ذِي الرَّحِمِ ‏ ‏الْكَاشِحِ ‏","","",""],[22431,22431,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ السَّائِبَةِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سُعَادَ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمَاءُ ‏ ‏مِنْ ‏ ‏الْمَاءِ ‏","","",""],[22432,22432,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏سَهْمِ بْنِ مِنْجَابٍ ‏ ‏عَنْ ‏ ‏قَزَعَةَ ‏ ‏عَنِ ‏ ‏الْقَرْثَعِ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏أَدْمَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْبَعَ رَكَعَاتٍ عِنْدَ زَوَالِ الشَّمْسِ قَالَ فَقُلْتُ يَا رَسُولَ اللَّهِ مَا هَذِهِ الرَّكَعَاتُ الَّتِي أَرَاكَ قَدْ أَدْمَنْتَهَا ‏ ‏قَالَ ‏ ‏إِنَّ أَبْوَابَ السَّمَاءِ تُفْتَحُ عِنْدَ زَوَالِ الشَّمْسِ فَلَا ‏ ‏تُرْتَجُ ‏ ‏حَتَّى يُصَلَّى الظُّهْرُ فَأُحِبُّ أَنْ يَصْعَدَ لِي فِيهَا خَيْرٌ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ تَقْرَأُ فِيهِنَّ كُلِّهِنَّ قَالَ قَالَ نَعَمْ قَالَ قُلْتُ فَفِيهَا سَلَامٌ فَاصِلٌ قَالَ لَا ‏","","",""],[22433,22433,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏سَعْدُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَامَ رَمَضَانَ ثُمَّ أَتْبَعَهُ سِتًّا مِنْ شَوَّالٍ فَذَلِكَ صِيَامُ الدَّهْرِ ‏","","",""],[22434,22434,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏مَرْثَدِ بْنِ عَبْدِ اللَّهِ الْيَزَنِيِّ ‏ ‏قَالَ ‏ ‏قَدِمَ عَلَيْنَا ‏ ‏أَبُو أَيُّوبَ ‏ ‏غَازِيًا ‏ ‏وَعُقْبَةُ بْنُ عَامِرٍ ‏ ‏يَوْمَئِذٍ عَلَى ‏ ‏مِصْرَ ‏ ‏فَأَخَّرَ الْمَغْرِبَ فَقَامَ إِلَيْهِ ‏ ‏أَبُو أَيُّوبَ ‏ ‏فَقَالَ مَا هَذِهِ الصَّلَاةُ يَا ‏ ‏عُقْبَةُ ‏ ‏فَقَالَ شُغِلْنَا قَالَ أَمَا وَاللَّهِ مَا بِي إِلَّا أَنْ يَظُنَّ النَّاسُ أَنَّكَ رَأَيْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصْنَعُ هَذَا أَمَا سَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَزَالُ أُمَّتِي بِخَيْرٍ ‏ ‏أَوْ عَلَى الْفِطْرَةِ ‏ ‏مَا لَمْ يُؤَخِّرُوا الْمَغْرِبَ إِلَى أَنْ يَشْتَبِكَ النُّجُومُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏مَرْثَدِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَدِمَ عَلَيْنَا ‏ ‏أَبُو أَيُّوبَ ‏ ‏وَعُقْبَةُ بْنُ عَامِرٍ ‏ ‏يَوْمَئِذٍ عَلَى ‏ ‏مِصْرَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[22435,22435,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَتَى أَحَدُكُمْ الْخَلَاءَ فَلَا يَسْتَقْبِلْ الْقِبْلَةَ وَلَا يَسْتَدْبِرْهَا وَلْيُشَرِّقْ وَلْيُغَرِّبْ ‏ ‏قَالَ ‏ ‏أَبُو أَيُّوبَ ‏ ‏فَلَمَّا أَتَيْنَا ‏ ‏الشَّامَ ‏ ‏وَجَدْنَا مَقَاعِدَ تَسْتَقْبِلُ الْقِبْلَةَ فَجَعَلْنَا نَنْحَرِفُ وَنَسْتَغْفِرُ اللَّهَ عَزَّ وَجَلَّ ‏","","",""],[22436,22436,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏سِمَاكٌ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ سَمُرَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا أَكَلَ طَعَامًا بَعَثَ بِفَضْلِهِ إِلَى ‏ ‏أَبِي أَيُّوبَ ‏ ‏قَالَ فَأُتِيَ يَوْمًا ‏ ‏بِقَصْعَةٍ ‏ ‏فِيهَا ثُومٌ فَبَعَثَ بِهَا قَالَ يَا رَسُولَ اللَّهِ أَحَرَامٌ هُوَ قَالَ ‏ ‏لَا وَلَكِنِّي أَكْرَهُ رِيحَهُ قَالَ فَإِنِّي أَكْرَهُ مَا تَكْرَهُ ‏","","",""],[22437,22437,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ عُثْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُوسَى بْنَ طَلْحَةَ ‏ ‏أَنَّ ‏ ‏أَبَا أَيُّوبَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ أَعْرَابِيًّا عَرَضَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ فِي مَسِيرٍ فَأَخَذَ ‏ ‏بِخِطَامِ ‏ ‏نَاقَتِهِ ‏ ‏أَوْ ‏ ‏بِزِمَامِ ‏ ‏نَاقَتِهِ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏أَوْ يَا ‏ ‏مُحَمَّدُ ‏ ‏أَخْبِرْنِي بِمَا يُقَرِّبُنِي مِنْ الْجَنَّةِ وَيُبَاعِدُنِي مِنْ النَّارِ قَالَ ‏ ‏تَعْبُدُ اللَّهَ وَلَا تُشْرِكُ بِهِ شَيْئًا وَتُقِيمُ الصَّلَاةَ ‏ ‏وَتُؤْتِي الزَّكَاةَ وَتَصِلُ الرَّحِمَ ‏","","",""],[22438,22438,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَوْنُ بْنُ أَبِي جُحَيْفَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ بَعْدَ مَا غَرَبَتْ الشَّمْسُ فَسَمِعَ صَوْتًا فَقَالَ ‏ ‏يَهُودُ ‏ ‏تُعَذَّبُ فِي قُبُورِهَا ‏","","",""],[22439,22439,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏وَاصِلٌ ‏ ‏عَنْ ‏ ‏أَبِي سَوْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَسْتَاكُ ‏ ‏مِنْ اللَّيْلِ مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثًا ‏ ‏وَإِذَا قَامَ ‏ ‏يُصَلِّي مِنْ اللَّيْلِ صَلَّى أَرْبَعَ رَكَعَاتٍ لَا يَتَكَلَّمُ وَلَا يَأْمُرُ بِشَيْءٍ وَيُسَلِّمُ بَيْنَ كُلِّ رَكْعَتَيْنِ وَبِهِ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا تَوَضَّأَ تَمَضْمَضَ وَمَسَحَ لِحْيَتَهُ مِنْ تَحْتِهَا بِالْمَاءِ ‏","","",""],[22440,22440,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏قُرَيْشُ بْنُ حَيَّانَ ‏ ‏عَنْ ‏ ‏أَبِي وَاصِلٍ ‏ ‏قَالَ ‏ ‏لَقِيتُ ‏ ‏أَبَا أَيُّوبَ الْأَنْصَارِيَّ ‏ ‏فَصَافَحَنِي فَرَأَى فِي أَظْفَارِي طُولًا فَقَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْأَلُ أَحَدُكُمْ عَنْ خَبَرِ السَّمَاءِ وَهُوَ يَدَعُ أَظْفَارَهُ كَأَظَافِيرِ الطَّيْرِ يَجْتَمِعُ فِيهَا الْجَنَابَةُ وَالْخَبَثُ وَالتَّفَثُ ‏ ‏وَلَمْ يَقُلْ ‏ ‏وَكِيعٌ ‏ ‏مَرَّةً الْأَنْصَارِيَّ ‏ ‏قَالَ غَيْرُهُ ‏ ‏أَبُو أَيُّوبَ الْعَتَكِيُّ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏سَبَقَهُ ‏ ‏لِسَانُهُ ‏ ‏يَعْنِي ‏ ‏وَكِيعٌ ‏ ‏فَقَالَ لَقِيتُ ‏ ‏أَبَا أَيُّوبَ الْأَنْصَارِيَّ ‏ ‏وَإِنَّمَا فَهُوَ ‏ ‏أَبُو أَيُّوبَ الْعَتَكِيُّ ‏","","",""],[22441,22441,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَالِكٍ يَعْنِي الْأَشْجَعِيَّ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏أَسْلَمَ ‏ ‏وَغِفَارَ ‏ ‏وَمُزَيْنَةَ ‏ ‏وَأَشْجَعَ ‏ ‏وَجُهَيْنَةَ ‏ ‏وَمَنْ كَانَ مِنْ ‏ ‏بَنِي كَعْبٍ ‏ ‏مَوَالِيَّ دُونَ النَّاسِ وَاللَّهُ وَرَسُولُهُ مَوْلَاهُمْ ‏","","",""],[22442,22442,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏أَوْ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَرَأَ فِي الْمَغْرِبِ ‏ ‏بِالْأَعْرَافِ ‏ ‏فِي الرَّكْعَتَيْنِ ‏","","",""],[22443,22443,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ حُسَيْنٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْتِرْ ‏ ‏بِخَمْسٍ فَإِنْ لَمْ تَسْتَطِعْ فَبِثَلَاثٍ فَإِنْ لَمْ تَسْتَطِعْ فَبِوَاحِدَةٍ فَإِنْ لَمْ تَسْتَطِعْ فَأَوْمِئْ ‏ ‏إِيمَاءً ‏","","",""],[22444,22444,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏دَاوُدُ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ عَشْرَ مَرَّاتٍ كُنَّ لَهُ كَعَدْلِ عِتْقِ عَشْرِ رِقَابٍ ‏ ‏أَوْ رَقَبَةٍ ‏","","",""],[22445,22445,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يِسَافٍ ‏ ‏عَنِ ‏ ‏رَبِيعِ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏امْرَأَةٍ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏قُلْ هُوَ اللَّهُ أَحَدٌ ‏ ‏تَعْدِلُ ‏ ‏ثُلُثَ الْقُرْآنِ ‏","","",""],[22446,22446,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ اللَّهِ بْنِ حُنَيْنٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏اخْتَلَفَ ‏ ‏الْمِسْوَرُ بْنُ مَخْرَمَةَ ‏ ‏وَابْنُ عَبَّاسٍ ‏ ‏فِي الْمُحْرِمِ يَغْسِلُ رَأْسَهُ ‏ ‏فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏يَغْسِلُ ‏ ‏وَقَالَ ‏ ‏الْمِسْوَرُ ‏ ‏لَا يَغْسِلُ ‏ ‏فَأَرْسَلُونِي إِلَى ‏ ‏أَبِي أَيُّوبَ ‏ ‏فَسَأَلْتُهُ ‏ ‏فَصَبَّ عَلَى رَأْسِهِ الْمَاءَ ثُمَّ أَقْبَلَ بِيَدَيْهِ وَأَدْبَرَ بِهِمَا ثُمَّ قَالَ هَكَذَا رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَلَ ‏","","",""],[22447,22447,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَمَعَ بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ ‏ ‏بِالْمُزْدَلِفَةِ ‏","","",""],[22448,22448,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُثْمَانَ بْنِ عَبْدِ اللَّهِ بْنِ مَوْهَبٍ ‏ ‏وَأَبُوهُ ‏ ‏عُثْمَانُ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّهُمَا سَمِعَا ‏ ‏مُوسَى بْنَ طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏أَنَّ رَجُلًا قَالَ يَا رَسُولَ اللَّهِ أَخْبِرْنِي بِعَمَلٍ يُدْخِلُنِي الْجَنَّةَ فَقَالَ الْقَوْمُ مَا لَهُ مَا لَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرَبٌ ‏ ‏مَا لَهُ قَالَ ‏ ‏تَعْبُدُ اللَّهَ لَا تُشْرِكُ بِهِ شَيْئًا وَتُقِيمُ الصَّلَاةَ ‏ ‏وَتُؤْتِي الزَّكَاةَ وَتَصِلُ الرَّحِمَ ‏ ‏ذَرْهَا ‏ ‏قَالَ كَأَنَّهُ كَانَ عَلَى ‏ ‏رَاحِلَتِهِ ‏","","",""],[22449,22449,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنِ ‏ ‏الْمُسَيَّبِ بْنِ رَافِعٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ الصَّلْتِ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏أَنَّهُ ‏ ‏كَانَ ‏ ‏يُصَلِّي أَرْبَعَ رَكَعَاتٍ قَبْلَ الظُّهْرِ فَقِيلَ لَهُ إِنَّكَ تُدِيمُ هَذِهِ الصَّلَاةَ فَقَالَ إِنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْعَلُهُ فَسَأَلْتُهُ فَقَالَ ‏ ‏إِنَّهَا سَاعَةٌ تُفْتَحُ فِيهَا أَبْوَابُ السَّمَاءِ فَأَحْبَبْتُ أَنْ يَرْتَفِعَ لِي فِيهَا عَمَلٌ صَالِحٌ ‏","","",""],[22450,22450,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو صَخْرٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو أَيُّوبَ الْأَنْصَارِيُّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةَ أُسْرِيَ بِهِ ‏ ‏مَرَّ عَلَى ‏ ‏إِبْرَاهِيمَ ‏ ‏فَقَالَ مَنْ مَعَكَ يَا ‏ ‏جِبْرِيلُ ‏ ‏قَالَ هَذَا ‏ ‏مُحَمَّدٌ ‏ ‏فَقَالَ لَهُ ‏ ‏إِبْرَاهِيمُ ‏ ‏مُرْ أُمَّتَكَ فَلْيُكْثِرُوا مِنْ ‏ ‏غِرَاسِ ‏ ‏الْجَنَّةِ فَإِنَّ تُرْبَتَهَا طَيِّبَةٌ وَأَرْضَهَا وَاسِعَةٌ قَالَ وَمَا ‏ ‏غِرَاسُ ‏ ‏الْجَنَّةِ قَالَ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ ‏","","",""],[22451,22451,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏وَحَدَّثَنِي ‏ ‏عَدِيُّ بْنُ ثَابِتٍ ‏ ‏وَمُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَمَعَ بَيْنَ الصَّلَاتَيْنِ ‏ ‏بِجَمْعٍ ‏","","",""],[22452,22452,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ بْنِ قُدَامَةَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يِسَافٍ ‏ ‏عَنِ ‏ ‏الرَّبِيعِ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنِ ‏ ‏امْرَأَةٍ ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَيُعْجِبُ أَحَدُكُمْ أَنْ يَقْرَأَ ثُلُثَ الْقُرْآنِ فِي لَيْلَةٍ فَإِنَّهُ ‏ ‏مَنْ قَرَأَ ‏ { ‏قُلْ هُوَ اللَّهُ أَحَدٌ اللَّهُ الصَّمَدُ ‏} ‏فِي لَيْلَةٍ فَقَدْ قَرَأَ لَيْلَتَئِذٍ ثُلُثَ الْقُرْآنِ ‏","","",""],[22453,22453,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَوْنِ بْنِ أَبِي جُحَيْفَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ وَجَبَتْ الشَّمْسُ قَالَ فَسَمِعَ صَوْتًا فَقَالَ ‏ ‏يَهُودُ ‏ ‏تُعَذَّبُ فِي قُبُورِهَا ‏","","",""],[22454,22454,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏وَرْقَاءَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏سَعْدِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَامَ رَمَضَانَ وَسِتًّا مِنْ شَوَّالٍ فَقَدْ صَامَ الدَّهْرَ ‏","","",""],[22455,22455,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏عِيسَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِذَا عَطَسَ أَحَدُكُمْ فَلْيَقُلْ الْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ وَلْيَقُلْ الَّذِي يَرُدُّ عَلَيْهِ يَرْحَمُكَ اللَّهُ وَلْيَقُلْ هُوَ ‏ ‏يَهْدِيكَ اللَّهُ وَيُصْلِحُ بَالَكَ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ ‏","","",""],[22456,22456,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ يَعْنِي ابْنَ كَرِيزٍ ‏ ‏عَنْ ‏ ‏شَيْخٍ ‏ ‏مِنْ أَهْلِ ‏ ‏مَكَّةَ ‏ ‏مِنْ ‏ ‏قُرَيْشٍ ‏ ‏عَنْ ‏ ‏أَبِي أيُوبِ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏وَجَدَ رَجُلٌ فِي ثَوْبِهِ قَمْلَةً فَأَخَذَهَا لِيَطْرَحَهَا فِي الْمَسْجِدِ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَفْعَلْ ارْدُدْهَا فِي ثَوْبِكَ حَتَّى تَخْرُجَ مِنْ الْمَسْجِدِ ‏","","",""],[22457,22457,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزُ بْنُ أَسَدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ يَعْنِي ابْنَ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَسْتَقْبِلُوا الْقِبْلَةَ بِفُرُوجِكُمْ وَلَا تَسْتَدْبِرُوهَا ‏","","",""],[22458,22458,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا ظِبْيَانَ ‏ ‏وَيَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي ظِبْيَانَ ‏ ‏قَالَ ‏ ‏غَزَا ‏ ‏أَبُو أَيُّوبَ ‏ ‏الرُّومَ ‏ ‏فَمَرِضَ فَلَمَّا حُضِرَ قَالَ أَنَا إِذَا مِتُّ فَاحْمِلُونِي فَإِذَا ‏ ‏صَافَعْتُمُ الْعَدُوَّ فَادْفِنُونِي تَحْتَ أَقْدَامِكُمْ وَسَأُحَدِّثُكُمْ حَدِيثًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا حَالِي هَذَا مَا حَدَّثْتُكُمُوهُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ مَاتَ لَا يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ الْجَنَّةَ ‏","","",""],[22459,22459,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعْدُ بْنُ سَعِيدٍ الْأَنْصَارِيُّ ‏ ‏أَخُو ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏أَخْبَرَنِي ‏ ‏عُمَرُ بْنُ ثَابِتٍ ‏ ‏رَجُلٌ مِنْ ‏ ‏بَنِي الْحَارِثِ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو أَيُّوبَ الْأَنْصَارِيُّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ صَامَ رَمَضَانَ ثُمَّ أَتْبَعَهُ سِتًّا مِنْ شَوَّالٍ فَذَاكَ صِيَامُ الدَّهْرِ ‏","","",""],[22460,22460,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ الْخَطْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏أَنَّهُ ‏ ‏صَلَّى مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجَّةِ الْوَدَاعِ صَلَاةَ الْمَغْرِبِ وَالْعِشَاءِ الْآخِرَةِ ‏ ‏بِالْمُزْدَلِفَةِ ‏","","",""],[22461,22461,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏حَنَشُ بْنُ الْحَارِثِ بْنِ لَقِيطٍ النَّخَعِيُّ الْأَشْجَعِيُّ ‏ ‏عَنْ ‏ ‏رِيَاحِ بْنِ الْحَارِثِ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏رَهْطٌ ‏ ‏إِلَى ‏ ‏عَلِيٍّ ‏ ‏بالرَّحْبَةِ ‏ ‏فَقَالُوا السَّلَامُ عَلَيْكَ يَا مَوْلَانَا قَالَ كَيْفَ أَكُونُ مَوْلَاكُمْ وَأَنْتُمْ قَوْمٌ عَرَبٌ قَالُوا سَمِعْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏غَدِيرِ خُمٍّ ‏ ‏يَقُولُ ‏ ‏مَنْ كُنْتُ مَوْلَاهُ فَإِنَّ هَذَا مَوْلَاهُ قَالَ ‏ ‏رِيَاحٌ ‏ ‏فَلَمَّا مَضَوْا تَبِعْتُهُمْ فَسَأَلْتُ مَنْ هَؤُلَاءِ قَالُوا نَفَرٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فِيهِمْ ‏ ‏أَبُو أَيُّوبَ الْأَنْصَارِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏حَنَشٌ ‏ ‏عَنْ ‏ ‏رِيَاحِ بْنِ الْحَارِثِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ قَوْمًا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏قَدِمُوا عَلَى ‏ ‏عَلِيٍّ ‏ ‏فِي ‏ ‏الرَّحْبَةِ ‏ ‏فَقَالَ مَنْ الْقَوْمُ قَالُوا مَوَالِيكَ يَا أَمِيرَ الْمُؤْمِنِينَ فَذَكَرَ مَعْنَاهُ ‏","","",""],[22462,22462,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنِ ‏ ‏الْمُسَيَّبِ بْنِ رَافِعٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي قَبْلَ الظُّهْرِ أَرْبَعًا فَقِيلَ لَهُ إِنَّكَ تُصَلِّي صَلَاةً تُدِيمُهَا فَقَالَ ‏ ‏إِنَّ أَبْوَابَ السَّمَاءِ تُفْتَحُ إِذَا زَالَتْ الشَّمْسُ فَلَا ‏ ‏تُرْتَجُ ‏ ‏حَتَّى يُصَلَّى الظُّهْرُ فَأُحِبُّ أَنْ يَصْعَدَ لِي إِلَى السَّمَاءِ خَيْرٌ ‏","","",""],[22463,22463,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ يَزِيدَ الْخَطْمِيِّ ‏ ‏أَنَّ ‏ ‏أَبَا أَيُّوبَ الْأَنْصَارِيَّ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ ‏ ‏صَلَّى مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجَّةِ الْوَدَاعِ الْمَغْرِبَ وَالْعِشَاءَ جَمِيعًا ‏ ‏بِالْمُزْدَلِفَةِ ‏","","",""],[22464,22464,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابُ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ لَهِيعَةَ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏أَنَّ ‏ ‏أَسْلَمَ أَبَا عِمْرَانَ التُّجِيبِيَّ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا أَيُّوبَ الْأَنْصَارِيَّ ‏ ‏يَقُولُ ‏ ‏صَفَفْنَا يَوْمَ ‏ ‏بَدْرٍ ‏ ‏فَنَدَرَتْ ‏ ‏مِنَّا ‏ ‏نَادِرَةٌ ‏ ‏أَمَامَ الصَّفِّ فَنَظَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَيْهِمْ فَقَالَ مَعِي مَعِي ‏ ‏وَكَذَا ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏مَعْمَرٌ ‏ ‏فَبَدَرَتْ ‏ ‏مِنَّا ‏ ‏بَادِرَةٌ ‏ ‏وَقَالَ صَفَفْنَا يَوْمَ ‏ ‏بَدْرٍ ‏","","",""],[22465,22465,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنْ ‏ ‏أَبِي رُهْمٍ السَّمَعِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ قَالَ حِينَ يُصْبِحُ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ يُحْيِي وَيُمِيتُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ عَشْرَ مَرَّاتٍ كَتَبَ اللَّهُ لَهُ بِكُلِّ وَاحِدَةٍ قَالَهَا عَشْرَ حَسَنَاتٍ وَحَطَّ اللَّهُ عَنْهُ بِهَا عَشْرَ سَيِّئَاتٍ وَرَفَعَهُ اللَّهُ بِهَا عَشْرَ دَرَجَاتٍ وَكُنَّ لَهُ كَعَشْرِ رِقَابٍ وَكُنَّ لَهُ ‏ ‏مَسْلَحَةً ‏ ‏مِنْ أَوَّلِ النَّهَارِ إِلَى آخِرِهِ وَلَمْ يَعْمَلْ يَوْمَئِذٍ عَمَلًا يَقْهَرُهُنَّ فَإِنْ قَالَ حِينَ يُمْسِي فَمِثْلُ ذَلِكَ ‏","","",""],[22466,22466,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏أَنَّ ‏ ‏أَسْلَمَ أَبَا عِمْرَانَ ‏ ‏حَدَّثَهُمْ أَنَّهُ سَمِعَ ‏ ‏أَبَا أَيُّوبَ ‏ ‏يَقُولُ ‏ ‏صَفَفْنَا يَوْمَ ‏ ‏بَدْرٍ ‏ ‏فَبَدَرَتْ ‏ ‏مِنَّا ‏ ‏بَادِرَةٌ ‏ ‏أَمَامَ الصَّفِّ فَنَظَرَ إِلَيْهِمْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَعِي مَعِي ‏","","",""],[22467,22467,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي الْخَيْرِ ‏ ‏عَنْ ‏ ‏أَبِي رُهْمٍ السَّمَعِيِّ ‏ ‏أَنَّ ‏ ‏أَبَا أَيُّوبَ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَزَلَ فِي بَيْتِنَا الْأَسْفَلِ وَكُنْتُ فِي الْغُرْفَةِ ‏ ‏فَأُهْرِيقَ ‏ ‏مَاءٌ فِي الْغُرْفَةِ فَقُمْتُ أَنَا ‏ ‏وَأُمُّ أَيُّوبَ ‏ ‏بِقَطِيفَةٍ ‏ ‏لَنَا نَتْبَعُ الْمَاءَ شَفَقَةَ يَخْلُصُ الْمَاءُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَزَلْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا مُشْفِقٌ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّهُ لَيْسَ يَنْبَغِي أَنْ نَكُونَ فَوْقَكَ انْتَقِلْ إِلَى الْغُرْفَةِ فَأَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَتَاعِهِ فَنُقِلَ وَمَتَاعُهُ قَلِيلٌ فَقُلْتُ يَا رَسُولَ اللَّهِ كُنْتَ تُرْسِلُ إِلَيَّ بِالطَّعَامِ فَأَنْظُرُ فَإِذَا رَأَيْتُ أَثَرَ أَصَابِعِكَ وَضَعْتُ يَدِي فِيهِ حَتَّى إِذَا كَانَ هَذَا الطَّعَامُ الَّذِي أَرْسَلْتَ بِهِ إِلَيَّ فَنَظَرْتُ فِيهِ فَلَمْ أَرَ فِيهِ أَثَرَ أَصَابِعِكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَجَلْ ‏ ‏إِنَّ فِيهِ بَصَلًا فَكَرِهْتُ أَنْ آكُلَهُ مِنْ أَجْلِ الْمَلَكِ الَّذِي يَأْتِينِي وَأَمَّا أَنْتُمْ فَكُلُوهُ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏قُلْتُ لِأَبِي إِنَّ رَجُلًا قَالَ مَنْ صَلَّى رَكْعَتَيْنِ بَعْدَ الْمَغْرِبِ فِي الْمَسْجِدِ لَمْ يُجْزِهِ إِلَّا أَنْ يُصَلِّيَهَا فِي بَيْتِهِ لِأَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏هَذِهِ مِنْ صَلَوَاتِ الْبُيُوتِ قَالَ مَنْ قَالَ هَذَا قُلْتُ ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ مَا أَحْسَنَ مَا قَالَ ‏ ‏أَوْ قَالَ مَا أَحْسَنَ مَا نَقَلَ ‏","","",""],[22468,22468,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ إِبْرَاهِيمَ التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ أَبِي يَحْيَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ اغْتَسَلَ يَوْمَ الْجُمُعَةِ وَمَسَّ مِنْ طِيبٍ إِنْ كَانَ عِنْدَهُ وَلَبِسَ مِنْ أَحْسَنِ ثِيَابِهِ ثُمَّ خَرَجَ حَتَّى يَأْتِيَ الْمَسْجِدَ فَيَرْكَعَ إِنْ بَدَا لَهُ وَلَمْ يُؤْذِ أَحَدًا ثُمَّ أَنْصَتَ إِذَا خَرَجَ إِمَامُهُ حَتَّى يُصَلِّيَ كَانَتْ كَفَّارَةً لِمَا بَيْنَهَا وَبَيْنَ الْجُمُعَةِ الْأُخْرَى ‏ ‏و قَالَ ‏ ‏فِي مَوْضِعٍ آخَرَ إِنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ كَعْبِ بْنِ مَالِكٍ السُّلَمِيَّ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏أَبَا أَيُّوبَ صَاحِبَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَهُ أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ اغْتَسَلَ يَوْمَ الْجُمُعَةِ وَزَادَ فِيهِ ثُمَّ خَرَجَ وَعَلَيْهِ ‏ ‏السَّكِينَةُ ‏ ‏حَتَّى يَأْتِيَ الْمَسْجِدَ ‏","","",""],[22469,22469,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَدِيُّ بْنُ ثَابِتٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏جَمَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ ‏ ‏بِجَمْعٍ ‏","","",""],[22470,22470,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ الْحَجَّاجِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُبَارَكٍ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ الْخَطْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يُصَلِّي الْمَغْرِبَ وَالْعِشَاءَ بِإِقَامَةٍ ‏","","",""],[22471,22471,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنِ ‏ ‏الْمُسَيَّبِ بْنِ رَافِعٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ مُدْرِكٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏أَبَا أَيُّوبَ ‏ ‏فَنَزَعَ خُفَّيْهِ فَنَظَرُوا إِلَيْهِ فَقَالَ أَمَا إِنِّي قَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ عَلَيْهِمَا وَلَكِنْ حُبِّبَ إِلَيَّ الْوُضُوءُ ‏","","",""],[22472,22472,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ السَّائِبَةِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سُعَادَ ‏ ‏وَكَانَ مَرْضِيًّا مِنْ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمَاءُ ‏ ‏مِنْ ‏ ‏الْمَاءِ ‏","","",""],[22473,22473,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏يَرْوِيهِ قَالَ ‏ ‏لَا يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلَاثَةِ أَيَّامٍ يَلْتَقِيَانِ فَيَصُدُّ هَذَا وَيَصُدُّ هَذَا وَخَيْرُهُمَا الَّذِي يَبْدَأُ بِالسَّلَامِ ‏","","",""],[22474,22474,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَتَى أَحَدُكُمْ الْغَائِطَ فَلَا يَسْتَقْبِلْ الْقِبْلَةَ وَلَا يَسْتَدْبِرْهَا وَلَكِنْ لِيُشَرِّقْ أَوْ لِيُغَرِّبْ ‏ ‏قَالَ ‏ ‏أَبُو أَيُّوبَ ‏ ‏فَلَمَّا قَدِمْنَا ‏ ‏الشَّامَ ‏ ‏وَجَدْنَا مَرَاحِيضَ جُعِلَتْ نَحْوَ الْقِبْلَةِ فَنَنْحَرِفُ وَنَسْتَغْفِرُ اللَّهَ ‏","","",""],[22475,22475,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَثَنا ‏ ‏حَجَّاجٌ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏وَرَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ اللَّهِ بْنِ حُنَيْنٍ ‏ ‏مَوْلَى آلِ ‏ ‏عَيَّاشٍ ‏ ‏وَقَالَ ‏ ‏رَوْحٌ ‏ ‏مَوْلَى ‏ ‏عَبَّاسٍ ‏ ‏أَنَّهُ أَخْبَرَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَبْدِ اللَّهِ بْنِ حُنَيْنٍ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏وَالْمِسْوَرِ ‏ ‏بِالْأَبْوَاءِ ‏ ‏فَتَحَدَّثْنَا حَتَّى ذَكَرْنَا غَسْلَ الْمُحْرِمِ رَأْسَهُ ‏ ‏فَقَالَ ‏ ‏الْمِسْوَرُ ‏ ‏لَا ‏ ‏وَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏بَلَى ‏ ‏فَأَرْسَلَنِي ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏إِلَى ‏ ‏أَبِي أَيُّوبَ ‏ ‏يَقْرَأُ عَلَيْكَ ابْنُ أَخِيكَ ‏ ‏عَبْدُ اللَّهِ بْنُ عَبَّاسٍ ‏ ‏السَّلَامَ وَيَسْأَلُكَ كَيْفَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَغْسِلُ رَأْسَهُ مُحْرِمًا قَالَ فَوَجَدَهُ ‏ ‏يَغْتَسِلُ بَيْنَ قَرْنَيْ بِئْرٍ قَدْ سُتِرَ عَلَيْهِ بِثَوْبٍ فَلَمَّا اسْتَبَنْتُ لَهُ ضَمَّ الثَّوْبَ إِلَى صَدْرِهِ حَتَّى بَدَا لِي وَجْهُهُ وَرَأَيْتُهُ وَإِنْسَانٌ قَائِمٌ يَصُبُّ عَلَى رَأْسِهِ الْمَاءَ قَالَ فَأَشَارَ ‏ ‏أَبُو أَيُّوبَ ‏ ‏بِيَدَيْهِ عَلَى رَأْسِهِ جَمِيعًا عَلَى جَمِيعِ رَأْسِهِ فَأَقْبَلَ بِهِمَا وَأَدْبَرَ فَقَالَ ‏ ‏الْمِسْوَرُ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏لَا ‏ ‏أُمَارِيكَ ‏ ‏أَبَدًا ‏ ‏قَالَ ‏ ‏الْحَجَّاجُ ‏ ‏وَرَوْحٌ ‏ ‏فَلَمَّا انْتَسَبْتُ لَهُ وَسَأَلْتُهُ ضَمَّ الثَّوْبَ إِلَى صَدْرِهِ حَتَّى بَدَا لِي رَأْسُهُ وَوَجْهُهُ وَإِنْسَانٌ قَائِمٌ ‏","","",""],[22476,22476,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏سَمِعْتُ ‏ ‏أَبَا أَيُّوبَ ‏ ‏يُخْبِرُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَسْتَقْبِلُوا الْقِبْلَةَ بِغَائِطٍ وَلَا بَوْلٍ وَلَكِنْ شَرِّقُوا أَوْ غَرِّبُوا ‏ ‏قَالَ ‏ ‏أَبُو أَيُّوبَ ‏ ‏فَقَدِمْنَا ‏ ‏الشَّامَ ‏ ‏فَوَجَدْنَا مَرَاحِيضَ جُعِلَتْ نَحْوَ الْقِبْلَةِ فَنَنْحَرِفُ وَنَسْتَغْفِرُ اللَّهَ ‏","","",""],[22477,22477,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ خَالِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلُّوا الْمَغْرِبَ لِفِطْرِ الصَّائِمِ وَبَادِرُوا طُلُوعَ النُّجُومِ ‏","","",""],[22478,22478,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْحَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏وحَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏أَبُو أَيُّوبَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْبَعٌ مِنْ سُنَنِ الْمُرْسَلِينَ التَّعَطُّرُ وَالنِّكَاحُ وَالسِّوَاكُ وَالْحَيَاءُ ‏","","",""],[22479,22479,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏مَرْثَدِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَدِمَ عَلَيْنَا ‏ ‏أَبُو أَيُّوبَ ‏ ‏وَعُقْبَةُ بْنُ عَامِرٍ ‏ ‏يَوْمَئِذٍ عَلَى ‏ ‏مِصْرَ ‏ ‏فَأَخَّرَ الْمَغْرِبَ فَقَامَ إِلَيْهِ ‏ ‏أَبُو أَيُّوبَ ‏ ‏فَقَالَ مَا هَذِهِ الصَّلَاةُ يَا ‏ ‏عُقْبَةُ ‏ ‏قَالَ شُغِلْنَا قَالَ أَمَا وَاللَّهِ مَا بِي إِلَّا أَنْ يَظُنَّ النَّاسُ أَنَّكَ رَأَيْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصْنَعُ هَذَا أَمَا سَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَزَالُ أُمَّتِي بِخَيْرٍ ‏ ‏أَوْ عَلَى الْفِطْرَةِ ‏ ‏مَا لَمْ يُؤَخِّرُوا الْمَغْرِبَ إِلَى أَنْ تَشْتَبِكَ النُّجُومُ ‏","","",""],[22480,22480,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ أَبِي زَائِدَةَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏قَالَ ‏ ‏مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ عَشْرَ مَرَّاتٍ كَانَ كَمَنْ أَعْتَقَ أَرْبَعَ رِقَابٍ مِنْ وَلَدِ ‏ ‏إِسْمَاعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ أَبِي زَائِدَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي السَّفَرِ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏رَبِيعِ بْنِ خُثَيْمٍ ‏ ‏بِمِثْلِ ذَلِكَ ‏ ‏قَالَ فَقُلْتُ ‏ ‏لِلَّربِيعِ ‏ ‏مِمَّنْ سَمِعْتَهُ ‏ ‏فَقَالَ ‏ ‏مِنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏فَقُلْتُ ‏ ‏لِعَمْرِو بْنِ مَيْمُونٍ ‏ ‏مِمَّنْ سَمِعْتَهُ ‏ ‏فَقَالَ ‏ ‏مِنْ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏فَقُلْتُ ‏ ‏لِابْنِ أَبِي لَيْلَى ‏ ‏مِمَّنْ سَمِعْتَهُ ‏ ‏قَالَ ‏ ‏مِنْ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏يُحَدِّثُهُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[22481,22481,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏وَصَالِحٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَنَّ ‏ ‏عَطَاءَ بْنَ يَزِيدَ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلَاثٍ يَلْتَقِيَانِ فَيَصُدُّ هَذَا وَيَصُدُّ هَذَا وَخَيْرُهُمَا الَّذِي يَبْدَأُ بِالسَّلَامِ ‏","","",""],[22482,22482,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ أَبِي صَالِحٍ ‏ ‏قَالَ ‏ ‏أَقْبَلَ ‏ ‏مَرْوَانُ ‏ ‏يَوْمًا فَوَجَدَ رَجُلًا وَاضِعًا وَجْهَهُ عَلَى الْقَبْرِ فَقَالَ أَتَدْرِي مَا تَصْنَعُ فَأَقْبَلَ عَلَيْهِ فَإِذَا هُوَ ‏ ‏أَبُو أَيُّوبَ ‏ ‏فَقَالَ نَعَمْ جِئْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَمْ آتِ الْحَجَرَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَبْكُوا عَلَى الدِّينِ إِذَا وَلِيَهُ أَهْلُهُ وَلَكِنْ ابْكُوا عَلَيْهِ إِذَا وَلِيَهُ غَيْرُ أَهْلِهِ ‏","","",""],[22483,22483,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي أَيُّوبَ ‏ ‏وَحَدَّثَنِي ‏ ‏شُرَحْبِيلُ بْنُ شَرِيكٍ الْمَعَافِرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ الْحُبُلِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا أَيُّوبَ الْأَنْصَارِيَّ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَدْوَةٌ فِي سَبِيلِ اللَّهِ ‏ ‏أَوْ رَوْحَةٌ ‏ ‏خَيْرٌ مِمَّا طَلَعَتْ عَلَيْهِ الشَّمْسُ وَغَرَبَتْ ‏","","",""],[22484,22484,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا عَطَسَ أَحَدُكُمْ فَلْيَقُلْ الْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ وَلْيَقُلْ الَّذِي يُشَمِّتُهُ يَرْحَمُكُمْ اللَّهُ وَلْيَقُلْ الَّذِي يَرُدُّ عَلَيْهِ ‏ ‏يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏قَالَ ‏ ‏وَقَدْ رَأَيْتُ أَخَاهُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ إِلَّا أَنَّهُ قَالَ ‏ ‏وَلْيَقُلْ هُوَ ‏ ‏يَهْدِيكَ اللَّهُ وَيُصْلِحُ بَالَكَ ‏ ‏أَوْ قَالَ ‏ ‏يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ ‏","","",""],[22485,22485,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏بُكَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ تِعْلَى ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏صَبْرِ ‏ ‏الدَّابَّةِ ‏ ‏قَالَ ‏ ‏أَبُو أَيُّوبَ ‏ ‏لَوْ كَانَتْ لِي دَجَاجَةٌ مَا ‏ ‏صَبَرْتُهَا ‏","","",""],[22486,22486,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏بُكَيْرٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ تِعْلَى ‏ ‏قَالَ ‏ ‏غَزَوْنَا مَعَ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ خَالِدِ بْنِ الْوَلِيدِ ‏ ‏فَأُتِيَ بِأَرْبَعَةِ ‏ ‏أَعْلَاجٍ ‏ ‏مِنْ الْعَدُوِّ فَأَمَرَ بِهِمْ فَقُتِلُوا ‏ ‏صَبْرًا ‏ ‏بِالنَّبْلِ فَبَلَغَ ذَلِكَ ‏ ‏أَبَا أَيُّوبَ ‏ ‏فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى عَنْ قَتْلِ ‏ ‏الصَّبْرِ ‏","","",""],[22487,22487,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏بُكَيْرُ بْنُ الْأَشَجِّ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏عُبَيْدَ بْنَ تِعْلَى ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا أَيُّوبَ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏صَبْرِ ‏ ‏الدَّابَّةِ ‏","","",""],[22488,22488,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏أَنَّهُ ‏ ‏كَانَ فِي سَهْوَةٍ لَهُ فَكَانَتْ الْغُولُ تَجِيءُ فَتَأْخُذُ فَشَكَاهَا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِذَا رَأَيْتَهَا فَقُلْ ‏ ‏بِسْمِ اللَّهِ أَجِيبِي رَسُولَ اللَّهِ قَالَ فَجَاءَتْ فَقَالَ لَهَا فَأَخَذَهَا فَقَالَتْ لَهُ إِنِّي لَا أَعُودُ فَأَرْسَلَهَا فَجَاءَ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا فَعَلَ أَسِيرُكَ قَالَ أَخَذْتُهَا فَقَالَتْ لِي إِنِّي لَا أَعُودُ فَأَرْسَلْتُهَا فَقَالَ إِنَّهَا عَائِدَةٌ فَأَخَذْتُهَا مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثًا ‏ ‏كُلَّ ذَلِكَ يَقُولُ لَا أَعُودُ وَيَجِيءُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَقُولُ مَا فَعَلَ أَسِيرُكَ فَيَقُولُ أَخَذْتُهَا فَيَقُولُ لَا أَعُودُ فَيَقُولُ إِنَّهَا عَائِدَةٌ فَأَخَذَهَا فَقَالَتْ أَرْسِلْنِي وَأُعَلِّمُكَ شَيْئًا تَقُولُ فَلَا يَقْرَبُكَ شَيْءٌ ‏ ‏آيَةَ الْكُرْسِيِّ ‏ ‏فَأَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ فَقَالَ صَدَقَتْ وَهِيَ كَذُوبٌ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏فَذَكَرَ هَذَا الْحَدِيثَ بِإِسْنَادِهِ ‏ ‏يَعْنِي حَدِيثَ الْغُولِ قَالَ ‏ ‏أَبُو أَيُّوبَ خَالِدُ بْنُ زَيْدٍ ‏","","",""],[22489,22489,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي ظِبْيَانَ ‏ ‏قَالَ ‏ ‏غَزَا ‏ ‏أَبُو أَيُّوبَ ‏ ‏مَعَ ‏ ‏يَزِيدَ بْنِ مُعَاوِيَةَ ‏ ‏قَالَ فَقَالَ إِذَا أَنَا مِتُّ فَأَدْخِلُونِي أَرْضَ الْعَدُوِّ فَادْفِنُونِي تَحْتَ أَقْدَامِكُمْ حَيْثُ تَلْقَوْنَ الْعَدُوَّ قَالَ ثُمَّ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ مَاتَ لَا يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ الْجَنَّةَ ‏","","",""],[22490,22490,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏وَحُجَيْنٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ سُفْيَانَ الثَّقَفِيِّ ‏ ‏أَنَّهُمْ غَزَوْا غَزْوَةَ السُّلَاسِلِ فَفَاتَهُمْ الْغَزْوُ فَرَابَطُوا ثُمَّ رَجَعُوا إِلَى ‏ ‏مُعَاوِيَةَ ‏ ‏وَعِنْدَهُ ‏ ‏أَبُو أَيُّوبَ ‏ ‏وَعُقْبَةُ بْنُ عَامِرٍ ‏ ‏فَقَالَ ‏ ‏عَاصِمٌ ‏ ‏يَا ‏ ‏أَبَا أَيُّوبَ ‏ ‏فَاتَنَا الْغَزْوُ الْعَامَ وَقَدْ أُخْبِرْنَا أَنَّهُ مَنْ صَلَّى فِي الْمَسْجِدِ ‏ ‏وَقَالَ ‏ ‏حُجَيْنٌ ‏ ‏الْمَسَاجِدِ الْأَرْبَعَةِ ‏ ‏غُفِرَ لَهُ ذَنْبُهُ فَقَالَ ابْنَ أَخِي أَدُلُّكَ عَلَى أَيْسَرَ مِنْ ذَلِكَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ تَوَضَّأَ كَمَا أُمِرَ وَصَلَّى كَمَا أُمِرَ غُفِرَ لَهُ مَا قَدَّمَ مِنْ عَمَلٍ أَكَذَاكَ يَا ‏ ‏عُقْبَةُ ‏ ‏قَالَ نَعَمْ ‏","","",""],[22491,22491,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ أَبِي الْوَلِيدِ ‏ ‏عَنْ ‏ ‏أَيُّوبَ بْنِ خَالِدِ بْنِ أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ صَاحِبِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهُ ‏ ‏اكْتُمِ ‏ ‏الْخِطْبَةَ ‏ ‏ثُمَّ تَوَضَّأْ فَأَحْسِنْ وُضُوءَكَ وَصَلِّ مَا كَتَبَ اللَّهُ لَكَ ثُمَّ احْمَدْ رَبَّكَ وَمَجِّدْهُ ثُمَّ قُلْ اللَّهُمَّ إِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ وَتَعْلَمُ وَلَا أَعْلَمُ أَنْتَ عَلَّامُ الْغُيُوبِ فَإِنْ رَأَيْتَ لِي فِي فُلَانَةَ ‏ ‏تُسَمِّيهَا بِاسْمِهَا خَيْرًا فِي دِينِي وَدُنْيَايَ وَآخِرَتِي وَإِنْ كَانَ غَيْرُهَا خَيْرًا لِي مِنْهَا فِي دِينِي وَدُنْيَايَ وَآخِرَتِي فَاقْضِ لِي بِهَا ‏ ‏أَوْ قَالَ فَاقْدِرْهَا لِي ‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏حَيْوَةُ ‏ ‏أَنَّ ‏ ‏الْوَلِيدَ بْنَ الْوَلِيدِ ‏ ‏أَخْبَرَهُ ‏ ‏فَذَكَرَهُ بِإِسْنَادِهِ وَمَعْنَاهُ مِائَةً وَاثْنَيْ عَشَرَ حَدِيثًا ‏","","",""],[22492,22492,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏سَمِعَ ‏ ‏عُرْوَةَ ‏ ‏يَقُولُ أَنَا ‏ ‏أَبُو حُمَيْدٍ السَّاعِدِيُّ ‏ ‏قَالَ ‏ ‏اسْتَعْمَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلًا مِنْ ‏ ‏الْأَزْدِ ‏ ‏يُقَالُ لَهُ ‏ ‏ابْنُ اللُّتْبِيَّةِ ‏ ‏عَلَى ‏ ‏صَدَقَةٍ ‏ ‏فَجَاءَ فَقَالَ هَذَا لَكُمْ وَهَذَا أُهْدِيَ لِي فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمِنْبَرِ فَقَالَ ‏ ‏مَا بَالُ الْعَامِلِ نَبْعَثُهُ فَيَجِيءُ فَيَقُولُ هَذَا لَكُمْ وَهَذَا أُهْدِيَ لِي أَفَلَا جَلَسَ فِي بَيْتِ أَبِيهِ وَأُمِّهِ فَيَنْظُرَ أَيُهْدَى إِلَيْهِ أَمْ لَا وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ لَا يَأْتِي أَحَدٌ مِنْكُمْ مِنْهَا بِشَيْءٍ إِلَّا جَاءَ بِهِ يَوْمَ الْقِيَامَةِ عَلَى رَقَبَتِهِ إِنْ كَانَ بَعِيرًا لَهُ ‏ ‏رُغَاءٌ ‏ ‏أَوْ بَقَرَةً لَهَا ‏ ‏خُوَارٌ ‏ ‏أَوْ شَاةً ‏ ‏تَيْعَرُ ‏ ‏ثُمَّ رَفَعَ يَدَيْهِ حَتَّى رَأَيْنَا عُفْرَةَ يَدَيْهِ ثُمَّ ‏ ‏قَالَ اللَّهُمَّ هَلْ بَلَّغْتُ ثَلَاثًا ‏ ‏وَزَادَ ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏قَالَ ‏ ‏أَبُو حُمَيْدٍ ‏ ‏سَمِعَ أُذُنِي وَأَبْصَرَ عَيْنِي وَسَلُوا ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏","","",""],[22493,22493,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْحَمِيدِ بْنِ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي حُمَيْدٍ السَّاعِدِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُهُ وَهُوَ فِي عَشَرَةٍ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحَدُهُمْ ‏ ‏أَبُو قَتَادَةَ بْنُ رِبْعِيٍّ ‏ ‏يَقُولُ أَنَا أَعْلَمُكُمْ بِصَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالُوا لَهُ مَا كُنْتَ أَقْدَمَنَا صُحْبَةً وَلَا أَكْثَرَنَا لَهُ تَبَاعَةً قَالَ بَلَى قَالُوا فَاعْرِضْ قَالَ كَانَ إِذَا قَامَ إِلَى الصَّلَاةِ ‏ ‏اعْتَدَلَ قَائِمًا وَرَفَعَ يَدَيْهِ حَتَّى حَاذَى بِهِمَا مَنْكِبَيْهِ فَإِذَا أَرَادَ أَنْ يَرْكَعَ رَفَعَ يَدَيْهِ حَتَّى يُحَاذِيَ بِهِمَا مَنْكِبَيْهِ ثُمَّ قَالَ اللَّهُ أَكْبَرُ فَرَكَعَ ثُمَّ اعْتَدَلَ فَلَمْ يَصُبَّ رَأْسَهُ وَلَمْ يَقْنَعْهُ وَوَضَعَ يَدَيْهِ عَلَى رُكْبَتَيْهِ ثُمَّ قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ ثُمَّ رَفَعَ وَاعْتَدَلَ حَتَّى رَجَعَ كُلُّ عَظْمٍ فِي مَوْضِعِهِ مُعْتَدِلًا ثُمَّ هَوَى سَاجِدًا وَقَالَ اللَّهُ أَكْبَرُ ثُمَّ ‏ ‏جَافَى ‏ ‏وَفَتَحَ عَضُدَيْهِ عَنْ بَطْنِهِ وَفَتَحَ أَصَابِعَ رِجْلَيْهِ ثُمَّ ثَنَى رِجْلَهُ الْيُسْرَى وَقَعَدَ عَلَيْهَا وَاعْتَدَلَ حَتَّى رَجَعَ كُلُّ عَظْمٍ فِي مَوْضِعِهِ ثُمَّ هَوَى سَاجِدًا وَقَالَ اللَّهُ أَكْبَرُ ثُمَّ ثَنَى رِجْلَهُ وَقَعَدَ عَلَيْهَا حَتَّى يَرْجِعَ كُلُّ عُضْوٍ إِلَى مَوْضِعِهِ ثُمَّ نَهَضَ فَصَنَعَ فِي الرَّكْعَةِ الثَّانِيَةِ مِثْلَ ذَلِكَ حَتَّى إِذَا قَامَ مِنْ السَّجْدَتَيْنِ كَبَّرَ وَرَفَعَ يَدَيْهِ حَتَّى يُحَاذِيَ بِهِمَا مَنْكِبَيْهِ كَمَا صَنَعَ حِينَ افْتَتَحَ الصَّلَاةَ ثُمَّ صَنَعَ كَذَلِكَ حَتَّى إِذَا كَانَتْ الرَّكْعَةُ الَّتِي تَنْقَضِي فِيهَا الصَّلَاةُ أَخَّرَ رِجْلَهُ الْيُسْرَى وَقَعَدَ عَلَى شِقِّهِ مُتَوَرِّكًا ثُمَّ سَلَّمَ ‏","","",""],[22494,22494,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سُلَيْمٍ ‏ ‏أَنَّهُ قَالَ أَخْبَرَنِي ‏ ‏أَبُو حُمَيْدٍ السَّاعِدِيُّ ‏ ‏أَنَّهُمْ قَالُوا ‏ ‏يَا رَسُولَ اللَّهِ كَيْفَ نُصَلِّي عَلَيْكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُولُوا ‏ ‏اللَّهُمَّ صَلِّ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏وَأَزْوَاجِهِ وَذُرِّيَّتِهِ كَمَا صَلَّيْتَ عَلَى آلِ ‏ ‏إِبْرَاهِيمَ ‏ ‏وَبَارِكْ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏وَأَزْوَاجِهِ وَذُرِّيَّتِهِ كَمَا بَارَكْتَ عَلَى آلِ ‏ ‏إِبْرَاهِيمَ ‏ ‏إِنَّكَ حَمِيدٌ مَجِيدٌ ‏","","",""],[22495,22495,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَبِي حُمَيْدٍ السَّاعِدِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏هَدَايَا الْعُمَّالِ ‏ ‏غُلُولٌ ‏","","",""],[22496,22496,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عِيسَى ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي حُمَيْدٍ ‏ ‏أَوْ ‏ ‏حُمَيْدَةَ ‏ ‏الشَّكُّ مِنْ ‏ ‏زُهَيْرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا خَطَبَ أَحَدُكُمْ امْرَأَةً فَلَا جُنَاحَ عَلَيْهِ أَنْ يَنْظُرَ إِلَيْهَا إِذَا كَانَ إِنَّمَا يَنْظُرُ إِلَيْهَا لِخِطْبَتِهِ وَإِنْ كَانَتْ لَا تَعْلَمُ ‏","","",""],[22497,22497,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عِيسَى ‏ ‏حَدَّثَنِي ‏ ‏مُوسَى بْنُ عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي حُمَيْدٍ ‏ ‏أَوْ ‏ ‏أَبِي حُمَيْدَةَ ‏ ‏قَالَ ‏ ‏وَقَدْ رَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا خَطَبَ أَحَدُكُمْ امْرَأَةً فَلَا جُنَاحَ عَلَيْهِ أَنْ يَنْظُرَ إِلَيْهَا إِذَا كَانَ إِنَّمَا يَنْظُرُ إِلَيْهَا لِخِطْبَتِهِ وَإِنْ كَانَتْ لَا تَعْلَمُ ‏","","",""],[22498,22498,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ يَحْيَى ‏ ‏عَنِ ‏ ‏الْعَبَّاسِ بْنِ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ ‏ ‏عَنْ ‏ ‏أَبِي حُمَيْدٍ السَّاعِدِيِّ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَامَ ‏ ‏تَبُوكَ ‏ ‏حَتَّى ‏ ‏جِئْنَا ‏ ‏وَادِيَ الْقُرَى ‏ ‏فَإِذَا امْرَأَةٌ فِي حَدِيقَةٍ لَهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَصْحَابِهِ ‏ ‏اخْرُصُوا ‏ ‏فَخَرَصَ ‏ ‏الْقَوْمُ ‏ ‏وَخَرَصَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَشَرَةَ ‏ ‏أَوْسُقٍ ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلْمَرْأَةِ ‏ ‏أَحْصِي مَا يَخْرُجُ مِنْهَا حَتَّى أَرْجِعَ إِلَيْكِ إِنْ شَاءَ اللَّهُ قَالَ فَخَرَجَ حَتَّى قَدِمَ ‏ ‏تَبُوكَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهَا سَتَبِيتُ عَلَيْكُمْ اللَّيْلَةَ رِيحٌ شَدِيدَةٌ فَلَا يَقُومُ مِنْكُمْ فِيهَا رَجُلٌ فَمَنْ كَانَ لَهُ بَعِيرٌ ‏ ‏فَلْيُوثِقْ ‏ ‏عِقَالَهُ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو حُمَيْدٍ ‏ ‏فَعَقَلْنَاهَا فَلَمَّا كَانَ مِنْ اللَّيْلِ هَبَّتْ عَلَيْنَا رِيحٌ شَدِيدَةٌ فَقَامَ فِيهَا رَجُلٌ فَأَلْقَتْهُ فِي جَبَلِ ‏ ‏طَيِّئٍ ‏ ‏ثُمَّ جَاءَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَلِكُ ‏ ‏أَيْلَةَ ‏ ‏فَأَهْدَى لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَغْلَةً بَيْضَاءَ فَكَسَاهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بُرْدًا وَكَتَبَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِبَحْرِهِ قَالَ ثُمَّ أَقْبَلَ وَأَقْبَلْنَا مَعَهُ ‏ ‏حَتَّى ‏ ‏جِئْنَا ‏ ‏وَادِيَ الْقُرَى ‏ ‏فَقَالَ لِلْمَرْأَةِ كَمْ حَدِيقَتُكِ قَالَتْ عَشَرَةُ ‏ ‏أَوْسُقٍ ‏ ‏خَرْصُ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي مُتَعَجِّلٌ فَمَنْ أَحَبَّ مِنْكُمْ أَنْ يَتَعَجَّلَ فَلْيَفْعَلْ قَالَ فَخَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَخَرَجْنَا مَعَهُ حَتَّى إِذَا أَوْفَى عَلَى ‏ ‏الْمَدِينَةِ ‏ ‏قَالَ هِيَ هَذِهِ ‏ ‏طَابَةُ ‏ ‏فَلَمَّا رَأَى ‏ ‏أُحُدًا ‏ ‏قَالَ هَذَا ‏ ‏أُحُدٌ ‏ ‏يُحِبُّنَا وَنُحِبُّهُ أَلَا أُخْبِرُكُمْ بِخَيْرِ دُورِ ‏ ‏الْأَنْصَارِ ‏ ‏قَالَ قُلْنَا بَلَى يَا رَسُولَ اللَّهِ قَالَ خَيْرُ دُورِ ‏ ‏الْأَنْصَارِ ‏ ‏بَنُو النَّجَّارِ ‏ ‏ثُمَّ دَارُ ‏ ‏بَنِي عَبْدِ الْأَشْهَلِ ‏ ‏ثُمَّ دَارُ ‏ ‏بَنِي سَاعِدَةَ ‏ ‏ثُمَّ فِي كُلِّ دُورِ ‏ ‏الْأَنْصَارِ ‏ ‏خَيْرٌ ‏","","",""],[22499,22499,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي حُمَيْدٍ السَّاعِدِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَحِلُّ لِامْرِئٍ أَنْ يَأْخُذَ مَالَ أَخِيهِ بِغَيْرِ حَقِّهِ وَذَلِكَ لِمَا حَرَّمَ اللَّهُ مَالَ الْمُسْلِمِ عَلَى الْمُسْلِمِ ‏","","",""],[22500,22500,"","","‏ ‏و قَالَ ‏ ‏عُبَيْدُ بْنُ أَبِي قُرَّةَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏حَدَّثَنِي ‏ ‏سُهَيْلُ بْنُ أَبِي صَالِحٍ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي حُمَيْدٍ السَّاعِدِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَحِلُّ لِلرَّجُلِ أَنْ يَأْخُذَ عَصَا أَخِيهِ بِغَيْرِ طِيبِ نَفْسِهِ وَذَلِكَ لِشِدَّةِ مَا حَرَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ مَالِ الْمُسْلِمِ عَلَى الْمُسْلِمِ ‏","","",""],[22501,22501,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ سَعِيدِ بْنِ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي حُمَيْدٍ ‏ ‏وَأَبِي أُسَيْدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا سَمِعْتُمْ الْحَدِيثَ عَنِّي تَعْرِفُهُ قُلُوبُكُمْ وَتَلِينُ لَهُ أَشْعَارُكُمْ وَأَبْشَارُكُمْ وَتَرَوْنَ أَنَّهُ مِنْكُمْ قَرِيبٌ فَأَنَا أَوْلَاكُمْ بِهِ وَإِذَا سَمِعْتُمْ الْحَدِيثَ عَنِّي تُنْكِرُهُ قُلُوبُكُمْ وَتَنْفِرُ مِنْهُ أَشْعَارُكُمْ وَأَبْشَارُكُمْ وَتَرَوْنَ أَنَّهُ مِنْكُمْ بَعِيدٌ فَأَنَا أَبْعَدُكُمْ مِنْهُ ‏ ‏وَشَكَّ فِيهِمَا ‏ ‏عُبَيْدُ بْنُ أَبِي قُرَّةَ ‏ ‏فَقَالَ عَنْ ‏ ‏أَبِي حُمَيْدٍ ‏ ‏أَوْ ‏ ‏أَبِي أُسَيْدٍ ‏ ‏وَقَالَ تَرَوْنَ أَنَّكُمْ مِنْهُ قَرِيبٌ ‏ ‏وَشَكَّ ‏ ‏أَبُو سَعِيدٍ ‏ ‏فِي أَحَدِهِمَا فِي إِذَا سَمِعْتُمْ الْحَدِيثَ عَنِّي ‏","","",""],[22502,22502,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ سَعِيدِ بْنِ سُوَيْدٍ الْأَنْصَارِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا حُمَيْدٍ ‏ ‏وَأَبَا أُسَيْدٍ ‏ ‏يَقُولَانِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ أَحَدُكُمْ الْمَسْجِدَ فَلْيَقُلْ اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ فَإِذَا خَرَجَ فَلْيَقُلْ اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ ‏","","",""],[22503,22503,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وزَكَرِيَّا بْنُ إِسْحَاقَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ أَخْبَرَنِي ‏ ‏أَبُو حُمَيْدٍ ‏ ‏أَنَّهُ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِقَدَحِ لَبَنٍ مِنْ ‏ ‏النَّقِيعِ ‏ ‏لَيْسَ بِمُخَمَّرٍ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا خَمَّرْتَهُ وَلَوْ بِعُودٍ تَعْرُضُهُ قَالَ ‏ ‏أَبُو حُمَيْدٍ ‏ ‏إِنَّمَا أَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْأَسْقِيَةِ أَنْ ‏ ‏تُوكَأَ ‏ ‏وَبِالْأَبْوَابِ أَنْ تُغْلَقَ لَيْلًا وَلَمْ يَذْكُرْ ‏ ‏زَكَرِيَّا ‏ ‏قَوْلَ ‏ ‏أَبِي حُمَيْدٍ ‏ ‏بِاللَّيْلِ ‏","","",""],[22504,22504,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمْةَ ‏ ‏عَنْ ‏ ‏مُعَيْقِيبٍ ‏ ‏قَالَ ‏ ‏ذَكَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَسْحَ فِي الْمَسْجِدِ ‏ ‏يَعْنِي الْحَصَى ‏ ‏فَقَالَ ‏ ‏إِنْ كُنْتَ لَا بُدَّ فَاعِلًا فَوَاحِدَةً ‏","","",""],[22505,22505,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏حَدَّثَنِي ‏ ‏مُعَيْقِيبٌ ‏ ‏قَالَ ‏ ‏قِيلَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَسْحُ فِي الْمَسْجِدِ ‏ ‏يَعْنِي الْحَصَى ‏ ‏فَقَالَ ‏ ‏إِنْ كُنْتَ لَا بُدَّ فَاعِلًا فَوَاحِدَةً ‏","","",""],[22506,22506,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ بْنُ عُتْبَةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُعَيْقِيبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيْلٌ ‏ ‏لِلْأَعْقَابِ ‏ ‏مِنْ النَّارِ ‏","","",""],[22507,22507,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏حَدَّثَنِي ‏ ‏مُعَيْقِيبٌ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِي الرَّجُلِ يُسَوِّي التُّرَابَ حَيْثُ يَسْجُدُ قَالَ ‏ ‏إِنْ كُنْتَ فَاعِلًا فَوَاحِدَةً ‏","","",""],[22508,22508,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏نَفَرٍ ‏ ‏مِنْ ‏ ‏بَنِي سَلِمَةَ ‏ ‏قَالُوا ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَالِسًا فَشَقَّ ثَوْبَهُ فَقَالَ إِنِّي ‏ ‏وَاعَدْتُ ‏ ‏هَدْيًا ‏ ‏يُشْعَرُ ‏ ‏الْيَوْمَ ‏","","",""],[22509,22509,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ حَلْحَلَةَ ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي طِخْفَةَ الْغِفَارِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏أَنَّهُ ‏ ‏ضَافَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَعَ نَفَرٍ قَالَ فَبِتْنَا عِنْدَهُ فَخَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ اللَّيْلِ يَطَّلِعُ فَرَآهُ مُنْبَطِحًا عَلَى وَجْهِهِ ‏ ‏فَرَكَضَهُ ‏ ‏بِرِجْلِهِ فَأَيْقَظَهُ وَقَالَ ‏ ‏هَذِهِ ضِجْعَةُ أَهْلِ النَّارِ ‏","","",""],[22510,22510,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏يَعِيشَ بْنِ طِخْفَةَ الْغِفَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏ضِفْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَنْ تَضَيَّفَهُ مِنْ الْمَسَاكِينِ فَخَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي اللَّيْلِ ‏ ‏يَتَعَاهَدُ ‏ ‏ضَيْفَهُ فَرَآنِي مُنْبَطِحًا عَلَى بَطْنِي فَرَكَضَنِي بِرِجْلِهِ وَقَالَ ‏ ‏لَا تَضْطَجِعْ هَذِهِ الضِّجْعَةَ فَإِنَّهَا ضِجْعَةٌ يَبْغَضُهَا اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[22511,22511,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏بَيْنَا أَنَا جَالِسٌ مَعَ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏إِذْ طَلَعَ عَلَيْنَا رَجُلٌ مِنْ ‏ ‏بَنِي غِفَارٍ ‏ ‏ابْنٌ لِعَبْدِ اللَّهِ بْنِ طِخْفَةَ ‏ ‏فَقَالَ ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَلَا تُخْبِرُنَا عَنْ خَبَرِ أَبِيكَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَبْدُ اللَّهِ بْنُ طِخْفَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا كَثُرَ الضَّيْفُ عِنْدَهُ قَالَ لِيَنْقَلِبْ كُلُّ رَجُلٍ بِضَيْفِهِ حَتَّى إِذَا كَانَ ذَاتَ لَيْلَةٍ اجْتَمَعَ عِنْدَهُ ضِيفَانٌ كَثِيرٌ وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيَنْقَلِبْ كُلُّ رَجُلٍ مَعَ جَلِيسِهِ قَالَ فَكُنْتُ مِمَّنْ انْقَلَبَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا دَخَلَ قَالَ يَا ‏ ‏عَائِشَةُ ‏ ‏هَلْ مِنْ شَيْءٍ قَالَتْ نَعَمْ ‏ ‏حُوَيْسَةُ ‏ ‏كُنْتُ أَعْدَدْتُهَا لِإِفْطَارِكَ قَالَ فَجَاءَتْ بِهَا فِي ‏ ‏قُعَيْبَةٍ ‏ ‏لَهَا فَتَنَاوَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْهَا قَلِيلًا فَأَكَلَهُ ثُمَّ قَالَ خُذُوا بِسْمِ اللَّهِ فَأَكَلْنَا مِنْهَا حَتَّى مَا نَنْظُرُ إِلَيْهَا ثُمَّ قَالَ هَلْ عِنْدَكِ مِنْ شَرَابٍ قَالَتْ نَعَمْ ‏ ‏لُبَيْنَةٌ كُنْتُ أَعْدَدْتُهَا لَكَ قَالَ ‏ ‏هَلُمِّيهَا فَجَاءَتْ بِهَا فَتَنَاوَلَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَفَعَهَا إِلَى ‏ ‏فِيهِ فَشَرِبَ قَلِيلًا ثُمَّ قَالَ اشْرَبُوا بِسْمِ اللَّهِ فَشَرِبْنَا حَتَّى وَاللَّهِ مَا نَنْظُرُ إِلَيْهَا ثُمَّ خَرَجْنَا فَأَتَيْنَا الْمَسْجِدَ فَاضْطَجَعْتُ عَلَى وَجْهِي فَخَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَعَلَ يُوقِظُ النَّاسَ الصَّلَاةَ الصَّلَاةَ وَكَانَ إِذَا خَرَجَ يُوقِظُ النَّاسَ لِلصَّلَاةِ فَمَرَّ بِي وَأَنَا عَلَى وَجْهِي فَقَالَ مَنْ هَذَا فَقُلْتُ أَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ طِخْفَةَ ‏ ‏فَقَالَ ‏ ‏إِنَّ هَذِهِ ضِجْعَةٌ يَكْرَهُهَا اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[22512,22512,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏هِشَامٍ الدَّسْتُوَائِيِّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏يَعِيشَ بْنِ طِخْفَةَ الْغِفَارِيِّ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَبِي ‏ ‏مِنْ ‏ ‏أَصْحَابِ الصُّفَّةِ ‏ ‏فَأَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِهِمْ فَجَعَلَ يَنْقَلِبُ الرَّجُلُ بِالرَّجُلِ وَالرَّجُلَيْنِ حَتَّى بَقِيتُ خَامِسَ خَمْسَةٍ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْطَلِقُوا فَانْطَلَقْنَا مَعَهُ إِلَى بَيْتِ ‏ ‏عَائِشَةَ ‏ ‏فَقَالَ يَا ‏ ‏عَائِشَةُ ‏ ‏أَطْعِمِينَا فَجَاءَتْ ‏ ‏بِحَشِيشَةٍ ‏ ‏فَأَكَلْنَا ثُمَّ جَاءَتْ ‏ ‏بِحَيْسَةٍ ‏ ‏مِثْلِ ‏ ‏الْقَطَاةِ ‏ ‏فَأَكَلْنَا ثُمَّ قَالَ يَا ‏ ‏عَائِشَةُ ‏ ‏اسْقِينَا فَجَاءَتْ ‏ ‏بِعُسٍّ ‏ ‏فَشَرِبْنَا ثُمَّ جَاءَتْ بِقَدَحٍ صَغِيرٍ فِيهِ لَبَنٌ فَشَرِبْنَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ شِئْتُمْ بِتُّمْ وَإِنْ شِئْتُمْ انْطَلَقْتُمْ ‏ ‏إِلَى الْمَسْجِدِ فَقُلْنَا لَا بَلْ نَنْطَلِقُ إِلَى الْمَسْجِدِ قَالَ فَبَيْنَا أَنَا فِي الْمَسْجِدِ مُضْطَجِعًا عَلَى بَطْنِي إِذَا رَجُلٌ يُحَرِّكُنِي بِرِجْلِهِ فَقَالَ ‏ ‏إِنَّ هَذِهِ ضِجْعَةٌ يَبْغَضُهَا اللَّهُ فَنَظَرْتُ فَإِذَا هُوَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ يَعْنِي ابْنَ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ يَعْنِي شَيْبَانَ ‏ ‏عَنْ ‏ ‏يَحْيَى يَعْنِي ابْنَ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يَعِيشُ بْنُ قَيْسِ بْنِ طِخْفَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَكَانَ أَبُوهُ مِنْ ‏ ‏أَهْلِ الصُّفَّةِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا فُلَانُ انْطَلِقْ بِهَذَا مَعَكَ ‏ ‏وَذَكَرَ مَعْنَاهُ ‏","","",""],[22513,22513,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏الْحُصَيْنُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ عَمْرِو بْنِ سَعْدِ بْنِ مُعَاذٍ ‏ ‏أَخُو ‏ ‏بَنِي عَبْدِ الْأَشْهَلِ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ ‏ ‏أَخِي ‏ ‏بَنِي عَبْدِ الْأَشْهَلِ ‏ ‏قَالَ ‏ ‏لَمَّا قَدِمَ ‏ ‏أَبُو الْحَيْسَرِ أَنَسُ بْنُ رَافِعٍ ‏ ‏مَكَّةَ ‏ ‏وَمَعَهُ فِتْيَةٌ مِنْ ‏ ‏بَنِي عَبْدِ الْأَشْهَلِ ‏ ‏فِيهِمْ ‏ ‏إِيَاسُ بْنُ مُعَاذٍ ‏ ‏يَلْتَمِسُونَ الْحِلْفَ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏عَلَى قَوْمِهِمْ مِنْ ‏ ‏الْخَزْرَجِ ‏ ‏سَمِعَ بِهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَاهُمْ فَجَلَسَ إِلَيْهِمْ فَقَالَ لَهُمْ هَلْ لَكُمْ إِلَى خَيْرٍ مِمَّا جِئْتُمْ لَهُ قَالُوا وَمَا ذَاكَ قَالَ ‏ ‏أَنَا رَسُولُ اللَّهِ بَعَثَنِي إِلَى الْعِبَادِ ‏ ‏أَدْعُوهُمْ إِلَى أَنْ يَعْبُدُوا اللَّهَ لَا يُشْرِكُوا بِهِ شَيْئًا وَأُنْزِلَ عَلَيَّ كِتَابٌ ثُمَّ ذَكَرَ الْإِسْلَامَ وَتَلَا عَلَيْهِمْ الْقُرْآنَ فَقَالَ ‏ ‏إِيَاسُ بْنُ مُعَاذٍ ‏ ‏وَكَانَ غُلَامًا حَدَثًا ‏ ‏أَيْ قَوْمِ هَذَا وَاللَّهِ خَيْرٌ مِمَّا جِئْتُمْ لَهُ قَالَ فَأَخَذَ ‏ ‏أَبُو جُلَيْسٍ أَنَسُ بْنُ رَافِعٍ ‏ ‏حَفْنَةً مِنْ ‏ ‏الْبَطْحَاءِ ‏ ‏فَضَرَبَ بِهَا فِي وَجْهِ ‏ ‏إِيَاسِ بْنِ مُعَاذٍ ‏ ‏وَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْهُمْ وَانْصَرَفُوا إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَكَانَتْ وَقْعَةُ بُعَاثٍ بَيْنَ ‏ ‏الْأَوْسِ ‏ ‏وَالْخَزْرَجِ ‏ ‏قَالَ ثُمَّ لَمْ يَلْبَثْ ‏ ‏إِيَاسُ بْنُ مُعَاذٍ ‏ ‏أَنْ هَلَكَ قَالَ ‏ ‏مَحْمُودُ بْنُ لَبِيدٍ ‏ ‏فَأَخْبَرَنِي مَنْ حَضَرَهُ مِنْ قَوْمِي عِنْدَ مَوْتِهِ أَنَّهُمْ لَمْ يَزَالُوا يَسْمَعُونَهُ يُهَلِّلُ اللَّهَ وَيُكَبِّرُهُ وَيَحْمَدُهُ وَيُسَبِّحُهُ حَتَّى مَاتَ فَمَا كَانُوا يَشُكُّونَ أَنْ قَدْ مَاتَ مُسْلِمًا لَقَدْ كَانَ اسْتَشْعَرَ الْإِسْلَامَ فِي ذَلِكَ الْمَجْلِسِ حِينَ سَمِعَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا سَمِعَ ‏","","",""],[22514,22514,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنِي ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ رَبِيعٍ ‏ ‏وَقَدْ ‏ ‏كَانَ عَقَلَ ‏ ‏مَجَّةً ‏ ‏مَجَّهَا ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي وَجْهِهِ مِنْ دَلْوٍ مِنْ بِئْرٍ لَهُمْ ‏","","",""],[22515,22515,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ بْنُ الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏عَبْدِ رَبِّهِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏مَنْ رَأَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَ ‏ ‏أَحْجَارِ الزَّيْتِ ‏ ‏يَدْعُو هَكَذَا وَأَشَارَ بِبَاطِنِ كَفَّيْهِ نَحْوَ وَجْهِهِ ‏","","",""],[22516,22516,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏لَيَحْمِي عَبْدَهُ الْمُؤْمِنَ مِنْ الدُّنْيَا وَهُوَ ‏ ‏يَحْمِيهِ ‏ ‏كَمَا تَحْمُونَ مَرِيضَكُمْ مِنْ الطَّعَامِ وَالشَّرَابِ تَخَافُونَهُ عَلَيْهِ ‏","","",""],[22517,22517,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ إِذَا أَحَبَّ قَوْمًا ابْتَلَاهُمْ فَمَنْ صَبَرَ فَلَهُ الصَّبْرُ وَمَنْ ‏ ‏جَزِعَ ‏ ‏فَلَهُ ‏ ‏الْجَزَعُ ‏","","",""],[22518,22518,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏عَاصِمُ بْنُ عُمَرَ بْنِ قَتَادَةَ الْأَنْصَارِيُّ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ ‏ ‏أَخِي ‏ ‏بَنِي عَبْدِ الْأَشْهَلِ ‏ ‏قَالَ ‏ ‏أَتَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّى بِنَا الْمَغْرِبَ فِي مَسْجِدِنَا فَلَمَّا سَلَّمَ مِنْهَا قَالَ ‏ ‏ارْكَعُوا هَاتَيْنِ الرَّكْعَتَيْنِ فِي بُيُوتِكُمْ ‏ ‏لِلسُّبْحَةِ ‏ ‏بَعْدَ الْمَغْرِبِ ‏","","",""],[22519,22519,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اثْنَتَانِ يَكْرَهُهُمَا ابْنُ ‏ ‏آدَمَ ‏ ‏الْمَوْتُ وَالْمَوْتُ خَيْرٌ لِلْمُؤْمِنِ مِنْ الْفِتْنَةِ وَيَكْرَهُ قِلَّةَ الْمَالِ وَقِلَّةُ الْمَالِ أَقَلُّ لِلْحِسَابِ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[22520,22520,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ قَتَادَةَ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏يَحْمِي عَبْدَهُ الْمُؤْمِنَ فِي الدُّنْيَا وَهُوَ يُحِبُّهُ كَمَا تَحْمُونَ مَرِيضَكُمْ الطَّعَامَ وَالشَّرَابَ تَخَافُونَ عَلَيْهِ ‏","","",""],[22521,22521,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏عَاصِمُ بْنُ عُمَرَ بْنِ قَتَادَةَ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ ‏ ‏قَالَ ‏ ‏أَتَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَنِي عَبْدِ الْأَشْهَلِ ‏ ‏فَصَلَّى بِهِمْ الْمَغْرِبَ فَلَمَّا سَلَّمَ قَالَ ‏ ‏ارْكَعُوا هَاتَيْنِ الرَّكْعَتَيْنِ فِي بُيُوتِكُمْ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏قُلْتُ لِأَبِي إِنَّ رَجُلًا قَالَ مَنْ صَلَّى رَكْعَتَيْنِ بَعْدَ الْمَغْرِبِ فِي الْمَسْجِدِ لَمْ تُجْزِهِ إِلَّا أَنْ يُصَلِّيَهُمَا فِي بَيْتِهِ لِأَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ هَذِهِ مِنْ صَلَوَاتِ الْبُيُوتِ قَالَ مَنْ قَالَ هَذَا قُلْتُ ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ مَا أَحْسَنَ مَا قَالَ ‏ ‏أَوْ مَا أَحْسَنَ مَا انْتَزَعَ ‏","","",""],[22522,22522,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ سُلَيْمَانَ بْنِ الْغَسِيلِ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ ‏ ‏قَالَ ‏ ‏كَسَفَتْ الشَّمْسُ يَوْمَ مَاتَ ‏ ‏إِبْرَاهِيمُ ابْنُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا كَسَفَتْ الشَّمْسُ لِمَوْتِ ‏ ‏إِبْرَاهِيمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الشَّمْسَ وَالْقَمَرَ آيَتَانِ مِنْ آيَاتِ اللَّهِ عَزَّ وَجَلَّ أَلَا وَإِنَّهُمَا لَا يَنْكَسِفَانِ لِمَوْتِ أَحَدٍ وَلَا لِحَيَاتِهِ فَإِذَا رَأَيْتُمُوهُمَا كَذَلِكَ فَافْزَعُوا إِلَى الْمَسَاجِدِ ثُمَّ قَامَ فَقَرَأَ فِيمَا نَرَى بَعْضَ ‏ ‏الر كِتَابٌ ‏ ‏ثُمَّ رَكَعَ ثُمَّ اعْتَدَلَ ثُمَّ سَجَدَ سَجْدَتَيْنِ ثُمَّ قَامَ فَفَعَلَ مِثْلَ مَا فَعَلَ فِي الْأُولَى ‏","","",""],[22523,22523,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ يَعْنِي ابْنَ الْهَادِ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ أَخْوَفَ مَا أَخَافُ عَلَيْكُمْ الشِّرْكُ الْأَصْغَرُ قَالُوا وَمَا الشِّرْكُ الْأَصْغَرُ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏الرِّيَاءُ ‏ ‏يَقُولُ اللَّهُ عَزَّ وَجَلَّ لَهُمْ يَوْمَ الْقِيَامَةِ ‏ ‏إِذَا جُزِيَ النَّاسُ بِأَعْمَالِهِمْ اذْهَبُوا إِلَى الَّذِينَ كُنْتُمْ ‏ ‏تُرَاءُونَ ‏ ‏فِي الدُّنْيَا فَانْظُرُوا هَلْ تَجِدُونَ عِنْدَهُمْ جَزَاءً ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُمَرَ الظَّفَرِيِّ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ أَخْوَفَ مَا أَخَافُ عَلَيْكُمْ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[22524,22524,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏مَوْلَى ‏ ‏الْمُطَّلِبِ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏لَيَحْمِي عَبْدَهُ الدُّنْيَا وَهُوَ يُحِبُّهُ كَمَا تَحْمُونَ مَرْضَاكُمْ الطَّعَامَ وَالشَّرَابَ تَخَوُّفًا لَهُ عَلَيْهِ ‏","","",""],[22525,22525,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏مَوْلَى ‏ ‏الْمُطَّلِبِ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَحَبَّ اللَّهُ قَوْمًا ابْتَلَاهُمْ فَمَنْ صَبَرَ فَلَهُ الصَّبْرُ وَمَنْ ‏ ‏جَزِعَ ‏ ‏فَلَهُ ‏ ‏الْجَزَعُ ‏","","",""],[22526,22526,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏الْحُصَيْنُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ عَمْرِو بْنِ سَعْدِ بْنِ مُعَاذٍ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏مَوْلَى ‏ ‏ابْنِ أَبِي أَحْمَدَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ يَقُولُ حَدِّثُونِي عَنْ رَجُلٍ دَخَلَ الْجَنَّةَ لَمْ يُصَلِّ قَطُّ فَإِذَا لَمْ يَعْرِفْهُ النَّاسُ سَأَلُوهُ مَنْ هُوَ فَيَقُولُ ‏ ‏أُصَيْرِمُ بَنِي عَبْدِ الْأَشْهَلِ ‏ ‏عَمْرُو بْنُ ثَابِتِ بْنِ وَقْشٍ ‏ ‏قَالَ ‏ ‏الْحُصَيْنُ ‏ ‏فَقُلْتُ ‏ ‏لِمَحْمُودِ بْنِ لَبِيدٍ ‏ ‏كَيْفَ كَانَ شَأْنُ ‏ ‏الْأُصَيْرِمِ ‏ ‏قَالَ كَانَ ‏ ‏يَأْبَى الْإِسْلَامَ عَلَى قَوْمِهِ فَلَمَّا كَانَ يَوْمُ ‏ ‏أُحُدٍ ‏ ‏وَخَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏أُحُدٍ ‏ ‏بَدَا لَهُ الْإِسْلَامُ فَأَسْلَمَ فَأَخَذَ سَيْفَهُ ‏ ‏فَغَدَا ‏ ‏حَتَّى أَتَى الْقَوْمَ ‏ ‏فَدَخَلَ فِي عُرْضِ النَّاسِ فَقَاتَلَ حَتَّى أَثْبَتَتْهُ الْجِرَاحَةُ قَالَ فَبَيْنَمَا رِجَالُ ‏ ‏بَنِي عَبْدِ الْأَشْهَلِ ‏ ‏يَلْتَمِسُونَ قَتْلَاهُمْ فِي الْمَعْرَكَةِ إِذَا هُمْ بِهِ فَقَالُوا وَاللَّهِ إِنَّ هَذَا ‏ ‏لَلْأُصَيْرِمُ ‏ ‏وَمَا جَاءَ لَقَدْ تَرَكْنَاهُ وَإِنَّهُ لَمُنْكِرٌ هَذَا الْحَدِيثَ فَسَأَلُوهُ مَا جَاءَ بِهِ قَالُوا مَا جَاءَ بِكَ يَا ‏ ‏عَمْرُو ‏ ‏أَحَرْبًا عَلَى قَوْمِكَ أَوْ رَغْبَةً فِي الْإِسْلَامِ قَالَ بَلْ رَغْبَةً فِي الْإِسْلَامِ آمَنْتُ بِاللَّهِ وَرَسُولِهِ وَأَسْلَمْتُ ثُمَّ أَخَذْتُ سَيْفِي ‏ ‏فَغَدَوْتُ ‏ ‏مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَاتَلْتُ حَتَّى أَصَابَنِي مَا أَصَابَنِي قَالَ ثُمَّ لَمْ يَلْبَثْ أَنْ مَاتَ فِي أَيْدِيهِمْ فَذَكَرُوهُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّهُ لَمِنْ أَهْلِ الْجَنَّةِ ‏","","",""],[22527,22527,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْفِرُوا بِالْفَجْرِ فَإِنَّهُ أَعْظَمُ لِلْأَجْرِ ‏","","",""],[22528,22528,"","","‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَجَدْتُ هَذَا الْحَدِيثَ فِي كِتَابِ أَبِي بِخَطِّهِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏أَخْوَفَ مَا أَخَافُ عَلَيْكُمْ الشِّرْكُ الْأَصْغَرُ قَالُوا يَا رَسُولَ اللَّهِ وَمَا الشِّرْكُ الْأَصْغَرُ قَالَ ‏ ‏الرِّيَاءُ ‏ ‏إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى يَقُولُ يَوْمَ ‏ ‏تُجَازَى الْعِبَادُ بِأَعْمَالِهِمْ اذْهَبُوا إِلَى الَّذِينَ كُنْتُمْ تُرَاءُونَ بِأَعْمَالِكُمْ فِي الدُّنْيَا فَانْظُرُوا هَلْ تَجِدُونَ عِنْدَهُمْ جَزَاءً ‏","","",""],[22529,22529,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مُعَاوِيَةَ بْنِ خَدِيجٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏رَجُلًا ‏ ‏مِنْ ‏ ‏كِنْدَةَ ‏ ‏يَقُولُ حَدَّثَنِي ‏ ‏رَجُلٌ مِنْ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَنْتَقِصُ أَحَدُكُمْ مِنْ صَلَاتِهِ شَيْئًا إِلَّا أَتَمَّهَا اللَّهُ عَزَّ وَجَلَّ مِنْ ‏ ‏سُبْحَتِهِ ‏","","",""],[22530,22530,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏حَدَّثَنِي ‏ ‏مَحْمُودُ بْنُ لَبِيدٍ ‏ ‏أَنَّهُ ‏ ‏عَقَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَقَلَ ‏ ‏مَجَّةً ‏ ‏مَجَّهَا ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ دَلْوٍ كَانَ فِي دَارِهِمْ ‏","","",""],[22531,22531,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا بْنِ أَبِي زَائِدَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ ‏ ‏قَالَ ‏ ‏اخْتَلَفَتْ سُيُوفُ الْمُسْلِمِينَ عَلَى الْيَمَانِ ‏ ‏أَبِي حُذَيْفَةَ ‏ ‏يَوْمَ ‏ ‏أُحُدٍ ‏ ‏وَلَا يَعْرِفُونَهُ فَقَتَلُوهُ ‏ ‏فَأَرَادَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏يَدِيَهُ ‏ ‏فَتَصَدَّقَ ‏ ‏حُذَيْفَةُ ‏ ‏بِدِيَتِهِ ‏ ‏عَلَى الْمُسْلِمِينَ ‏","","",""],[22532,22532,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ ‏ { ‏أَلْهَاكُمْ التَّكَاثُرُ ‏ ‏فَقَرَأَهَا حَتَّى بَلَغَ ‏ ‏لَتُسْأَلُنَّ يَوْمَئِذٍ عَنْ النَّعِيمِ ‏} ‏قَالُوا يَا رَسُولَ اللَّهِ عَنْ أَيِّ نَعِيمٍ نُسْأَلُ وَإِنَّمَا هُمَا الْأَسْوَدَانِ الْمَاءُ وَالتَّمْرُ وَسُيُوفُنَا عَلَى رِقَابِنَا وَالْعَدُوُّ حَاضِرٌ فَعَنْ أَيِّ نَعِيمٍ نُسْأَلُ قَالَ إِنَّ ذَلِكَ سَيَكُونُ ‏","","",""],[22533,22533,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ بْنُ جَعْفَرٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرٌو ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَحَبَّ اللَّهُ قَوْمًا ابْتَلَاهُمْ فَمَنْ صَبَرَ فَلَهُ الصَّبْرُ وَمَنْ ‏ ‏جَزِعَ ‏ ‏فَلَهُ ‏ ‏الْجَزَعُ ‏","","",""],[22534,22534,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏نَوْفَلِ بْنِ مُعَاوِيَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ فَاتَتْهُ الصَّلَاةُ فَكَأَنَّمَا ‏ ‏وُتِرَ ‏ ‏أَهْلَهُ وَمَالَهُ ‏","","",""],[22535,22535,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ ‏ ‏بَنِي ضَمْرَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ قَوْمِهِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْعَقِيقَةِ ‏ ‏فَقَالَ ‏ ‏لَا أُحِبُّ ‏ ‏الْعُقُوقَ ‏ ‏وَلَكِنْ مَنْ وُلِدَ لَهُ وَلَدٌ فَأَحَبَّ أَنْ ‏ ‏يَنْسُكَ ‏ ‏عَلَيْهِ ‏ ‏أَوْ عَنْهُ ‏ ‏فَلْيَفْعَلْ ‏","","",""],[22536,22536,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَوْ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَنَّهُ قَالَ ‏ ‏شَهِدْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعَرَفَةَ ‏ ‏فَسُئِلَ عَنْ ‏ ‏الْعَقِيقَةِ ‏ ‏فَقَالَ ‏ ‏لَا أُحِبُّ ‏ ‏الْعُقُوقَ ‏ ‏وَلَكِنْ مَنْ وُلِدَ لَهُ وَلَدٌ فَأَحَبَّ أَنَّ ‏ ‏يَنْسُكَ ‏ ‏عَنْهُ فَلْيَفْعَلْ ‏","","",""],[22537,22537,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏زَيْدٍ يَعْنِي ابْنَ أَسْلَمَ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ ‏ ‏بَنِي سُلَيْمٍ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّهُ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِفِضَّةٍ فَقَالَ هَذِهِ مِنْ مَعْدِنٍ لَنَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَتَكُونُ مَعَادِنُ يُحْضِرُهَا شِرَارُ النَّاسِ ‏","","",""],[22538,22538,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنَ ‏ ‏الْأَنْصَارِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ نَسْتَقْبِلَ الْقِبْلَتَيْنِ بِبَوْلٍ أَوْ ‏ ‏غَائِطٍ ‏","","",""],[22539,22539,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ بَنِي حَارِثَةَ ‏ ‏أَنَّ رَجُلًا ‏ ‏وَجَأَ ‏ ‏نَاقَةً فِي ‏ ‏لَبَّتِهَا ‏ ‏بِوَتِدٍ وَخَشِيَ أَنْ تَفُوتَهُ فَسَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَهُ ‏ ‏أَوْ أَمَرَهُمْ ‏ ‏بِأَكْلِهَا ‏","","",""],[22540,22540,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ بَنِي أَسَدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَسْأَلُ رَجُلٌ وَلَهُ ‏ ‏أُوقِيَّةٌ ‏ ‏أَوْ ‏ ‏عَدْلُهَا ‏ ‏إِلَّا سَأَلَ ‏ ‏إِلْحَافًا ‏","","",""],[22541,22541,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏بَعْضِ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رُئِيَ ‏ ‏بِالْعَرْجِ ‏ ‏وَهُوَ يَصُبُّ عَلَى رَأْسِهِ الْمَاءَ مِنْ الْحَرِّ ‏ ‏أَوْ مِنْ الْعَطَشِ ‏ ‏وَهُوَ صَائِمٌ ‏","","",""],[22542,22542,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ أَسْلَمَ ‏ ‏أَنَّهُ لُدِغَ فَذَكَرَ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ أَنَّكَ قُلْتَ حِينَ أَمْسَيْتَ ‏ ‏أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ لَمْ تَضُرَّكَ ‏ ‏قَالَ ‏ ‏سُهَيْلٌ ‏ ‏فَكَانَ أَبِي إِنْ لُدِغَ أَحَدٌ مِنَّا يَقُولُ قَالَهَا فَإِنْ قَالُوا نَعَمْ قَالَ كَأَنَّهُ يَرَى أَنَّهَا لَا تَضُرُّهُ ‏","","",""],[22543,22543,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏بَعْضِ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُوشِكُ أَنْ يَغْلِبَ عَلَى الدُّنْيَا ‏ ‏لُكَعُ ‏ ‏بْنُ ‏ ‏لُكَعٍ ‏ ‏وَأَفْضَلُ النَّاسِ مُؤْمِنٌ بَيْنَ كَرِيمَتَيْنِ لَمْ يَرْفَعْهُ ‏","","",""],[22544,22544,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏عُبَيْدٍ مَوْلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سُئِلَ أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُ بِصَلَاةٍ بَعْدَ الْمَكْتُوبَةِ ‏ ‏أَوْ سِوَى الْمَكْتُوبَةِ ‏ ‏قَالَ نَعَمْ ‏ ‏بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ ‏","","",""],[22545,22545,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ ‏ ‏وَابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏حَدَّثَهُمْ ‏ ‏فِي مَجْلِسِ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏قَالَ ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏شَيْخٍ ‏ ‏فِي مَجْلِسِ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏عُبَيْدٍ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ امْرَأَتَيْنِ صَامَتَا وَأَنَّ رَجُلًا قَالَ يَا رَسُولَ اللَّهِ إِنَّ هَاهُنَا امْرَأَتَيْنِ قَدْ صَامَتَا وَإِنَّهُمَا قَدْ كَادَتَا أَنْ تَمُوتَا مِنْ الْعَطَشِ فَأَعْرَضَ عَنْهُ ‏ ‏أَوْ سَكَتَ ‏ ‏ثُمَّ عَادَ ‏ ‏وَأُرَاهُ قَالَ ‏ ‏بِالْهَاجِرَةِ ‏ ‏قَالَ يَا نَبِيَّ اللَّهِ إِنَّهُمَا وَاللَّهِ قَدْ مَاتَتَا أَوْ كَادَتَا أَنْ تَمُوتَا قَالَ ادْعُهُمَا قَالَ فَجَاءَتَا قَالَ فَجِيءَ بِقَدَحٍ ‏ ‏أَوْ ‏ ‏عُسٍّ ‏ ‏فَقَالَ لِإِحْدَاهُمَا قِيئِي فَقَاءَتْ قَيْحًا ‏ ‏أَوْ دَمًا ‏ ‏وَصَدِيدًا وَلَحْمًا حَتَّى قَاءَتْ نِصْفَ الْقَدَحِ ثُمَّ قَالَ لِلْأُخْرَى قِيئِي فَقَاءَتْ مِنْ قَيْحٍ وَدَمٍ وَصَدِيدٍ وَلَحْمٍ ‏ ‏عَبِيطٍ ‏ ‏وَغَيْرِهِ حَتَّى مَلَأَتْ الْقَدَحَ ثُمَّ قَالَ ‏ ‏إِنَّ هَاتَيْنِ صَامَتَا عَمَّا أَحَلَّ اللَّهُ وَأَفْطَرَتَا عَلَى مَا حَرَّمَ اللَّهُ عَزَّ وَجَلَّ عَلَيْهِمَا جَلَسَتْ إِحْدَاهُمَا إِلَى الْأُخْرَى فَجَعَلَتَا يَأْكُلَانِ لُحُومَ النَّاسِ ‏","","",""],[22546,22546,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏التَّيْمِيِّ ‏ ‏قَالَ ‏ ‏طَرَأَ عَلَيْنَا ‏ ‏رَجُلٌ ‏ ‏فِي مَجْلِسِ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏فَحَدَّثَنَا عَنْ ‏ ‏عُبَيْدٍ مَوْلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَسُئِلَ عَنْ صَلَاةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ ‏ ‏صَلَاتَهُ بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ غِيَاثٍ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ ‏ ‏أَبِي عُثْمَانَ ‏ ‏قَالَ فَقَالَ ‏ ‏رَجُلٌ ‏ ‏مِنْ الْقَوْمِ ‏ ‏حَدَّثَنَا ‏ ‏سَعْدٌ ‏ ‏أَوْ ‏ ‏عُبَيْدٌ ‏ ‏عُثْمَانُ بْنُ غِيَاثٍ ‏ ‏الَّذِي يَشُكُّ ‏ ‏مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُمْ ‏ ‏أُمِرُوا بِصِيَامٍ قَالَ فَجَاءَ رَجُلٌ بَعْضَ النَّهَارِ فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ فُلَانًا وَفُلَانَةَ قَدْ بَلَغَهُمَا الْجَهْدُ فَذَكَرَ مَعْنَى حَدِيثِ ‏ ‏يَزِيدَ ‏ ‏وَابْنِ أَبِي عُبَيْدٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏","","",""],[22547,22547,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ ثَعْلَبَةَ بْنِ صُعَيْرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَوْمَ ‏ ‏أُحُدٍ ‏ ‏زَمِّلُوهُمْ ‏ ‏فِي ثِيَابِهِمْ قَالَ وَجَعَلَ يَدْفِنُ فِي الْقَبْرِ ‏ ‏الرَّهْطَ ‏ ‏قَالَ وَقَالَ قَدِّمُوا أَكْثَرَهُمْ قُرْآنًا ‏","","",""],[22548,22548,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ ثَعْلَبَةَ بْنِ صُعَيْرٍ ‏ ‏قَالَ ‏ ‏لَمَّا أَشْرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى قَتْلَى ‏ ‏أُحُدٍ ‏ ‏فَقَالَ ‏ ‏أَشْهَدُ عَلَى هَؤُلَاءِ مَا مِنْ مَجْرُوحٍ جُرِحَ فِي اللَّهِ عَزَّ وَجَلَّ إِلَّا بَعَثَهُ اللَّهُ يَوْمَ الْقِيَامَةِ وَجُرْحُهُ ‏ ‏يَدْمَى اللَّوْنُ لَوْنُ الدَّمِ وَالرِّيحُ رِيحُ ‏ ‏الْمِسْكِ ‏ ‏انْظُرُوا أَكْثَرَهُمْ جَمْعًا لِلْقُرْآنِ فَقَدِّمُوهُ أَمَامَهُمْ فِي الْقَبْرِ ‏","","",""],[22549,22549,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ ثَعْلَبَةَ بْنِ أَبِي صُعَيْرٍ ‏ ‏وَثَبَّتَنِيهِ ‏ ‏مَعْمَرٌ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَشْرَفَ عَلَى قَتْلَى ‏ ‏أُحُدٍ ‏ ‏فَقَالَ إِنِّي ‏ ‏أَشْهَدُ عَلَى هَؤُلَاءِ ‏ ‏زَمِّلُوهُمْ ‏ ‏بِكُلُومِهِمْ ‏ ‏وَدِمَائِهِمْ ‏","","",""],[22550,22550,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي صُعَيْرٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ يَوْمُ ‏ ‏أُحُدٍ ‏ ‏أَشْرَفَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الشُّهَدَاءِ الَّذِينَ قُتِلُوا يَوْمَئِذٍ فَقَالَ ‏ ‏زَمِّلُوهُمْ ‏ ‏بِدِمَائِهِمْ فَإِنِّي قَدْ شَهِدْتُ عَلَيْهِمْ فَكَانَ يُدْفَنُ الرَّجُلَانِ وَالثَّلَاثَةُ فِي الْقَبْرِ الْوَاحِدِ وَيُسْأَلُ أَيُّهُمْ كَانَ أَقْرَأَ لِلْقُرْآنِ فَيُقَدِّمُونَهُ ‏ ‏قَالَ ‏ ‏جَابِرٌ ‏ ‏فَدُفِنَ أَبِي وَعَمِّي يَوْمَئِذٍ فِي قَبْرٍ وَاحِدٍ ‏","","",""],[22551,22551,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ ثَعْلَبَةَ بْنِ صُعَيْرٍ ‏ ‏أَنَّ ‏ ‏أَبَا جَهْلٍ ‏ ‏قَالَ حِينَ الْتَقَى الْقَوْمُ ‏ ‏اللَّهُمَّ أَقْطَعَنَا الرَّحِمَ وَآتَانَا بِمَا لَا نَعْرِفُهُ فَأَحْنِهِ الْغَدَاةَ فَكَانَ الْمُسْتَفْتِحَ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ مُسْلِمٍ الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ ثَعْلَبَةَ بْنِ صُعَيْرٍ الْعُذْرِيِّ ‏ ‏وَفِيمَا قَرَأَ عَلَى ‏ ‏يَعْقُوبَ الْعُذْرِيِّ ‏ ‏حَلِيفِ ‏ ‏بَنِي زُهْرَةَ ‏ ‏قَالَ ‏ ‏أَشْرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى أَصْحَابِ ‏ ‏أُحُدٍ ‏ ‏فَذَكَرَ مَعْنَى حَدِيثِ ‏ ‏يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏رَجُلٌ ‏ ‏فِي حَلْقَةِ ‏ ‏أَبِي عُثْمَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعْدٌ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُمْ ‏ ‏أُمِرُوا بِصِيَامِ يَوْمٍ فَجَاءَ رَجُلٌ بَعْضَ النَّهَارِ فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ فُلَانَةَ وَفُلَانَةَ قَدْ بَلَغَهُمَا الْجَهْدُ فَأَعْرَضَ عَنْهُ فَذَكَرَ الْحَدِيثَ ‏","","",""],[22552,22552,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ وَقَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ ثَعْلَبَةَ بْنُ صُعَيْرٍ الْعُذْرِيُّ ‏ ‏خَطَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّاسَ قَبْلَ الْفِطْرِ بِيَوْمَيْنِ فَقَالَ ‏ ‏أَدُّوا ‏ ‏صَاعًا ‏ ‏مِنْ بُرٍّ أَوْ قَمْحٍ بَيْنَ اثْنَيْنِ أَوْ ‏ ‏صَاعًا ‏ ‏مِنْ تَمْرٍ أَوْ ‏ ‏صَاعًا ‏ ‏مِنْ شَعِيرٍ عَلَى كُلِّ حُرٍّ وَعَبْدٍ وَصَغِيرٍ وَكَبِيرٍ ‏","","",""],[22553,22553,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏حَمَّادَ بْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏صَدَقَةِ الْفِطْرِ ‏ ‏فَحَدَّثَنِي عَنْ ‏ ‏نُعْمَانَ بْنِ رَاشِدٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ثَعْلَبَةَ بْنِ أَبِي صُعَيْرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَدُّوا صَاعًا مِنْ قَمْحٍ أَوْ ‏ ‏صَاعًا ‏ ‏مِنْ ‏ ‏بُرٍّ ‏ ‏وَشَكَّ ‏ ‏حَمَّادٌ ‏ ‏عَنْ كُلِّ اثْنَيْنِ صَغِيرٍ أَوْ كَبِيرٍ ذَكَرٍ أَوْ أُنْثَى حُرٍّ أَوْ مَمْلُوكٍ غَنِيٍّ أَوْ فَقِيرٍ أَمَّا غَنِيُّكُمْ ‏ ‏فَيُزَكِّيهِ اللَّهُ وَأَمَّا فَقِيرُكُمْ فَيُرَدُّ عَلَيْهِ أَكْثَرُ مِمَّا يُعْطِي ‏","","",""],[22554,22554,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏قَالَ قَرَأَهُ عَلَيَّ ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ ثَعْلَبَةَ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَسَحَ وَجْهَهُ أَنَّهُ رَأَى ‏ ‏سَعْدَ بْنَ أَبِي وَقَّاصٍ ‏ ‏يُوتِرُ بِرَكْعَةٍ وَاحِدَةٍ لَا يَزِيدُ عَلَيْهَا حَتَّى يَقُومَ مِنْ جَوْفِ اللَّيْلِ ‏","","",""],[22555,22555,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَبْدِ رَبِّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنِي ‏ ‏الزُّبَيْدِيُّ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ ثَعْلَبَةَ بْنِ صُعَيْرٍ الْعُذْرِيِّ ‏ ‏قَالَ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏مَسَحَ وَجْهَهُ زَمَنَ الْفَتْحِ ‏","","",""],[22556,22556,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ ثَعْلَبَةَ بْنِ صُعَيْرٍ الْعُذْرِيُّ ‏ ‏قَالَ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏مَسَحَ وَجْهَهُ زَمَنَ الْفَتْحِ أَنَّهُ رَأَى ‏ ‏سَعْدَ بْنَ أَبِي وَقَّاصٍ ‏ ‏كَانَ ‏ ‏سَعْدٌ ‏ ‏قَدْ شَهِدَ ‏ ‏بَدْرًا ‏ ‏مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوتِرُ بِرَكْعَةٍ وَاحِدَةٍ بَعْدَ صَلَاةِ الْعِشَاءِ ‏ ‏يَعْنِي الْعَتَمَةَ ‏ ‏لَا يَزِيدُ عَلَيْهَا حَتَّى يَقُومَ مِنْ جَوْفِ اللَّيْلِ ‏","","",""],[22557,22557,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏الْقَسَامَةِ ‏ ‏فِي الدَّمِ قَالَ ‏ ‏كَانَتْ ‏ ‏الْقَسَامَةُ ‏ ‏فِي الْجَاهِلِيَّةِ ‏ ‏عَنْ ‏ ‏حَدِيثِ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏وَسُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏رِجَالٍ مِنْ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَقَرَّهَا عَلَى مَا كَانَتْ عَلَيْهِ فِي الْجَاهِلِيَّةِ وَقَضَى بِهَا بَيْنَ نَاسٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فِي قَتِيلٍ ادَّعَوْهُ عَلَى ‏ ‏الْيَهُودِ ‏","","",""],[22558,22558,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ ثَعْلَبَةَ بْنِ صُعَيْرٍ الْعُذْرِيِّ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏مَسَحَ عَلَى وَجْهِهِ وَأَدْرَكَ ‏ ‏أَصْحَابَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ كَانُوا يَنْهَوْنِي عَنْ الْقُبْلَةِ تَخَوُّفًا أَنْ أَتَقَرَّبَ لِأَكْثَرَ مِنْهَا ثُمَّ الْمُسْلِمُونَ الْيَوْمَ يَنْهَوْنَ عَنْهَا وَيَقُولُ قَائِلُهُمْ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ لَهُ مِنْ حِفْظِ اللَّهِ مَا لَيْسَ لِأَحَدٍ ‏","","",""],[22559,22559,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَدِيِّ بْنِ الْخِيَارِ ‏ ‏أَنَّ ‏ ‏رَجُلًا مِنَ الْأَنْصَارِ ‏ ‏حَدَّثَهُ ‏ ‏أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ فِي مَجْلِسٍ فَسَارَّهُ ‏ ‏يَسْتَأْذِنُهُ فِي قَتْلِ رَجُلٍ مِنْ الْمُنَافِقِينَ فَجَهَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَلَيْسَ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ قَالَ الْأَنْصَارِيُّ بَلَى يَا رَسُولَ اللَّهِ وَلَا شَهَادَةَ لَهُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَيْسَ يَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ قَالَ بَلَى يَا رَسُولَ اللَّهِ وَلَا شَهَادَةَ لَهُ أَلَيْسَ ‏ ‏يُصَلِّي قَالَ بَلَى يَا رَسُولَ اللَّهِ وَلَا صَلَاةَ لَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُولَئِكَ الَّذِينَ نَهَانِي اللَّهُ عَنْهُمْ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَدِيِّ بْنِ الْخِيَارِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَدِيٍّ الْأَنْصَارِيِّ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَا هُوَ جَالِسٌ إِذْ جَاءَهُ رَجُلٌ ‏ ‏يَعْنِي يَسْتَأْذِنُهُ أَيْ يُسَارُّهُ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[22560,22560,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏قَالَ قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏وَأَخْبَرَنِي ‏ ‏عُمَرُ بْنُ ثَابِتٍ الْأَنْصَارِيُّ ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏بَعْضُ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَوْمَئِذٍ لِلنَّاسِ وَهُوَ يُحَذِّرُهُمْ فِتْنَةَ ‏ ‏الدَّجَّالِ ‏ ‏تَعْلَمُونَ أَنَّهُ لَنْ يَرَى أَحَدٌ مِنْكُمْ رَبَّهُ عَزَّ وَجَلَّ حَتَّى يَمُوتَ وَإِنَّهُ مَكْتُوبٌ بَيْنَ عَيْنَيْهِ كَافِرٌ يَقْرَؤُهُ مَنْ كَرِهَ عَمَلَهُ ‏","","",""],[22561,22561,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِجَدِّهِ جَدِّ ‏ ‏سَعِيدٍ ‏ ‏مَا اسْمُكَ قَالَ ‏ ‏حَزْنٌ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَلْ أَنْتَ ‏ ‏سَهْلٌ ‏ ‏فَقَالَ لَا أُغَيِّرُ اسْمًا سَمَّانِيهِ أَبِي ‏ ‏قَالَ ‏ ‏ابْنُ الْمُسَيَّبِ ‏ ‏فَمَا زَالَتْ فِينَا حُزُونَةٌ بَعْدُ ‏","","",""],[22562,22562,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏لَمَّا حَضَرَتْ ‏ ‏أَبَا طَالِبٍ ‏ ‏الْوَفَاةُ دَخَلَ عَلَيْهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعِنْدَهُ ‏ ‏أَبُو جَهْلٍ ‏ ‏وَعَبْدُ اللَّهِ بْنُ أَبِي أُمَيَّةَ ‏ ‏فَقَالَ أَيْ عَمِّ قُلْ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ كَلِمَةً ‏ ‏أُحَاجُّ ‏ ‏بِهَا لَكَ عِنْدَ اللَّهِ عَزَّ وَجَلَّ فَقَالَ ‏ ‏أَبُو جَهْلٍ ‏ ‏وَعَبْدُ اللَّهِ بْنُ أَبِي أُمَيَّةَ ‏ ‏يَا ‏ ‏أَبَا طَالِبٍ ‏ ‏أَتَرْغَبُ عَنْ مِلَّةِ ‏ ‏عَبْدِ الْمُطَّلِبِ ‏ ‏قَالَ فَلَمْ يَزَالَا يُكَلِّمَانِهِ حَتَّى قَالَ آخِرَ شَيْءٍ كَلَّمَهُمْ بِهِ عَلَى مِلَّةِ ‏ ‏عَبْدِ الْمُطَّلِبِ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَأَسْتَغْفِرَنَّ لَكَ مَا لَمْ أُنْهَ عَنْكَ فَنَزَلَتْ ‏ { ‏مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُولِي قُرْبَى مِنْ بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَابُ الْجَحِيمِ ‏} ‏قَالَ فَنَزَلَتْ فِيهِ ‏ { ‏إِنَّكَ لَا تَهْدِي مَنْ أَحْبَبْتَ ‏}","","",""],[22563,22563,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏طَارِقٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَبِي ‏ ‏مِمَّنْ بَايَعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَحْتَ الشَّجَرَةِ بَيْعَةَ الرِّضْوَانِ فَقَالَ ‏ ‏انْطَلَقْنَا فِي ‏ ‏قَابِلٍ ‏ ‏حَاجِّينَ فَعُمِّيَ عَلَيْنَا مَكَانُهَا فَإِنْ كَانَتْ بَيَّنَتْ لَكُمْ فَأَنْتُمْ أَعْلَمُ ‏","","",""],[22564,22564,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏طَارِقٍ ‏ ‏قَالَ ‏ ‏ذُكِرَ عِنْدَ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏الشَّجَرَةُ ‏ ‏فَقَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏أَنَّهُ ‏ ‏كَانَ ذَلِكَ الْعَامَ مَعَهُمْ فَنَسُوهَا مِنْ الْعَامِ الْمُقْبِلِ ‏","","",""],[22565,22565,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عَامِرِ بْنِ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏حَارِثَةَ بْنِ النُّعْمَانِ ‏ ‏قَالَ ‏ ‏مَرَرْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَعَهُ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏جَالِسٌ فِي الْمَقَاعِدِ فَسَلَّمْتُ عَلَيْهِ ثُمَّ أَجَزْتُ فَلَمَّا رَجَعْتُ وَانْصَرَفَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏هَلْ رَأَيْتَ الَّذِي كَانَ مَعِي قُلْتُ نَعَمْ قَالَ فَإِنَّهُ ‏ ‏جِبْرِيلُ ‏ ‏وَقَدْ رَدَّ عَلَيْكَ السَّلَامَ ‏","","",""],[22566,22566,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الرِّجَالِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُمَرَ ‏ ‏مَوْلَى ‏ ‏غُفْرَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏ثَعْلَبَةَ بْنِ أَبِي مَالِكٍ ‏ ‏عَنْ ‏ ‏حَارِثَةَ بْنِ النُّعْمَانِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَّخِذُ أَحَدُكُمْ ‏ ‏السَّائِمَةَ ‏ ‏فَيَشْهَدُ الصَّلَاةَ فِي جَمَاعَةٍ فَتَتَعَذَّرُ عَلَيْهِ ‏ ‏سَائِمَتُهُ ‏ ‏فَيَقُولُ لَوْ طَلَبْتُ ‏ ‏لِسَائِمَتِي ‏ ‏مَكَانًا هُوَ أَكْلَأُ مِنْ هَذَا فَيَتَحَوَّلُ وَلَا يَشْهَدُ إِلَّا الْجُمُعَةَ فَتَتَعَذَّرُ عَلَيْهِ ‏ ‏سَائِمَتُهُ ‏ ‏فَيَقُولُ لَوْ طَلَبْتُ ‏ ‏لِسَائِمَتِي ‏ ‏مَكَانًا هُوَ ‏ ‏أَكْلَأُ ‏ ‏مِنْ هَذَا فَيَتَحَوَّلُ فَلَا يَشْهَدُ الْجُمُعَةَ وَلَا الْجَمَاعَةَ فَيُطْبَعُ عَلَى قَلْبِهِ ‏","","",""],[22567,22567,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أُمِّ الدَّرْدَاءِ ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عَاصِمٍ الْأَشْعَرِيِّ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ السَّقِيفَةِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَيْسَ مِنْ ‏ ‏امْبِرِّ ‏ ‏امْصِيَامُ فِي ‏ ‏امْسَفَرِ ‏","","",""],[22568,22568,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَنَّ ‏ ‏صَفْوَانَ بْنَ عَبْدِ اللَّهِ بْنِ صَفْوَانَ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أُمِّ الدَّرْدَاءِ ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عَاصِمٍ الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏ابْنُ بَكْرِ ‏ ‏ابْنِ عَاصِمٍ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ مِنْ الْبِرِّ الصِّيَامُ فِي السَّفَرِ ‏","","",""],[22569,22569,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ عَبْدِ اللَّهِ بْنِ صَفْوَانَ ‏ ‏عَنْ ‏ ‏أُمِّ الدَّرْدَاءِ ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عَاصِمٍ الْأَشْعَرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ مِنْ الْبِرِّ الصِّيَامُ فِي السَّفَرِ ‏","","",""],[22570,22570,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنَ الْأَنْصَارِ ‏ ‏أَنَّ ‏ ‏الْأَنْصَارِيَّ أَخْبَرَ ‏ ‏عَطَاءً ‏ ‏أَنَّهُ قَبَّلَ امْرَأَتَهُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ صَائِمٌ فَأَمَرَ امْرَأَتَهُ فَسَأَلَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَلِكَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ رَسُولَ اللَّهِ يَفْعَلُ ذَلِكَ فَأَخْبَرَتْهُ امْرَأَتُهُ فَقَالَ إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُرَخَّصُ لَهُ فِي أَشْيَاءَ فَارْجِعِي إِلَيْهِ فَقُولِي لَهُ فَرَجَعَتْ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ قَالَ إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُرَخَّصُ لَهُ فِي أَشْيَاءَ فَقَالَ ‏ ‏أَنَا أَتْقَاكُمْ لِلَّهِ وَأَعْلَمُكُمْ بِحُدُودِ اللَّهِ ‏","","",""],[22571,22571,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏جُنَادَةُ بْنُ أَبِي أُمَيَّةَ ‏ ‏أَمِيرًا عَلَيْنَا فِي الْبَحْرِ سِتَّ سِنِينَ فَخَطَبَنَا ذَاتَ يَوْمٍ فَقَالَ دَخَلْنَا عَلَى ‏ ‏رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقُلْنَا لَهُ حَدِّثْنَا بِمَا سَمِعْتَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا تُحَدِّثْنَا بِمَا سَمِعْتَ مِنْ النَّاسِ قَالُوا قَالَ فَشَدَّدُوا عَلَيْهِ فَقَالَ قَامَ فِينَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أُنْذِرُكُمْ ‏ ‏الْمَسِيحَ الدَّجَّالَ ‏ ‏أُنْذِرُكُمْ ‏ ‏الْمَسِيحَ الدَّجَّالَ ‏ ‏وَهُوَ رَجُلٌ مَمْسُوحُ الْعَيْنِ ‏ ‏قَالَ ‏ ‏ابْنُ عَوْنٍ ‏ ‏أَظُنُّهُ قَالَ الْيُسْرَى ‏ ‏يَمْكُثُ فِي الْأَرْضِ أَرْبَعِينَ صَبَاحًا مَعَهُ جِبَالُ خُبْزٍ وَأَنْهَارُ مَاءٍ يَبْلُغُ سُلْطَانُهُ كُلَّ ‏ ‏مَنْهَلٍ ‏ ‏لَا يَأْتِي أَرْبَعَةَ مَسَاجِدَ فَذَكَرَ ‏ ‏الْمَسْجِدَ الْحَرَامَ ‏ ‏وَالْمَسْجِدَ الْأَقْصَى ‏ ‏وَالطُّورَ ‏ ‏وَالْمَدِينَةَ ‏ ‏غَيْرَ أَنَّ مَا كَانَ مِنْ ذَلِكَ فَاعْلَمُوا أَنَّ اللَّهَ لَيْسَ بِأَعْوَرَ لَيْسَ اللَّهُ بِأَعْوَرَ لَيْسَ اللَّهُ بِأَعْوَرَ ‏ ‏قَالَ ‏ ‏ابْنُ عَوْنٍ ‏ ‏وَأَظُنُّ فِي حَدِيثِهِ ‏ ‏يُسَلَّطُ عَلَى رَجُلٍ مِنْ الْبَشَرِ فَيَقْتُلُهُ ثُمَّ ‏ ‏يُحْيِيهِ وَلَا يُسَلَّطُ عَلَى غَيْرِهِ ‏","","",""],[22572,22572,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏جُنَادَةَ بْنِ أَبِي أُمَيَّةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَتَيْتُ ‏ ‏رَجُلًا مِنْ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ لَهُ حَدِّثْنِي حَدِيثًا سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الدَّجَّالِ ‏ ‏وَلَا تُحَدِّثْنِي عَنْ غَيْرِكَ وَإِنْ كَانَ عِنْدَكَ مُصَدَّقًا فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَنْذَرْتُكُمْ فِتْنَةَ ‏ ‏الدَّجَّالِ ‏ ‏فَلَيْسَ مِنْ ‏ ‏نَبِيٍّ إِلَّا أَنْذَرَهُ قَوْمَهُ ‏ ‏أَوْ أُمَّتَهُ ‏ ‏وَإِنَّهُ ‏ ‏آدَمُ ‏ ‏جَعْدٌ ‏ ‏أَعْوَرُ عَيْنِهِ الْيُسْرَى وَإِنَّهُ يُمْطِرُ وَلَا يُنْبِتُ الشَّجَرَةَ وَإِنَّهُ يُسَلَّطُ عَلَى نَفْسٍ فَيَقْتُلُهَا ثُمَّ ‏ ‏يُحْيِيهَا وَلَا يُسَلَّطُ عَلَى غَيْرِهَا وَإِنَّهُ مَعَهُ جَنَّةٌ وَنَارٌ وَنَهْرٌ وَمَاءٌ وَجَبَلُ خُبْزٍ وَإِنَّ جَنَّتَهُ نَارٌ وَنَارَهُ جَنَّةٌ وَإِنَّهُ يَلْبَثُ فِيكُمْ أَرْبَعِينَ صَبَاحًا يَرِدُ فِيهَا كُلَّ مَنْهَلٍ إِلَّا أَرْبَعَ مَسَاجِدَ ‏ ‏مَسْجِدَ الْحَرَامِ ‏ ‏وَمَسْجِدَ الْمَدِينَةِ ‏ ‏وَالطُّورِ ‏ ‏وَمَسْجِدَ الْأَقْصَى ‏ ‏وَإِنْ شَكَلَ عَلَيْكُمْ أَوْ شُبِّهَ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ لَيْسَ بِأَعْوَرَ ‏","","",""],[22573,22573,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏وَمَنْصُورٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏جُنَادَةَ بْنِ أَبِي أُمَيَّةَ الْأَزْدِيِّ ‏ ‏قَالَ ‏ ‏ذَهَبْتُ أَنَا وَرَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏إِلَى ‏ ‏رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْنَا حَدِّثْنَا مَا سَمِعْتَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُذْكَرُ فِي ‏ ‏الدَّجَّالِ ‏ ‏وَلَا تُحَدِّثْنَا عَنْ غَيْرِهِ وَإِنْ كَانَ مُصَدَّقًا قَالَ خَطَبَنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَنْذَرْتُكُمْ ‏ ‏الدَّجَّالَ ‏ ‏ثَلَاثًا فَإِنَّهُ لَمْ يَكُنْ نَبِيٌّ قَبْلِي إِلَّا قَدْ أَنْذَرَهُ أُمَّتَهُ وَإِنَّهُ فِيكُمْ أَيَّتُهَا الْأُمَّةُ وَإِنَّهُ ‏ ‏جَعْدٌ ‏ ‏آدَمُ ‏ ‏مَمْسُوحُ الْعَيْنِ الْيُسْرَى مَعَهُ جَنَّةٌ وَنَارٌ فَنَارُهُ جَنَّةٌ وَجَنَّتُهُ نَارٌ وَمَعَهُ جَبَلٌ مِنْ خُبْزٍ وَنَهْرٌ مِنْ مَاءٍ وَإِنَّهُ يُمْطِرُ الْمَطَرَ وَلَا يُنْبِتُ الشَّجَرَ وَإِنَّهُ يُسَلَّطُ عَلَى نَفْسٍ فَيَقْتُلُهَا وَلَا يُسَلَّطُ عَلَى غَيْرِهَا وَإِنَّهُ يَمْكُثُ فِي الْأَرْضِ أَرْبَعِينَ صَبَاحًا يَبْلُغُ فِيهَا كُلَّ ‏ ‏مَنْهَلٍ ‏ ‏وَلَا يَقْرَبُ أَرْبَعَةَ مَسَاجِدَ ‏ ‏مَسْجِدَ الْحَرَامِ ‏ ‏وَمَسْجِدَ الْمَدِينَةِ ‏ ‏وَمَسْجِدَ الطُّورِ ‏ ‏وَمَسْجِدَ الْأَقْصَى ‏ ‏وَمَا يُشَبَّهُ عَلَيْكُمْ فَإِنَّ رَبَّكُمْ لَيْسَ بِأَعْوَرَ ‏","","",""],[22574,22574,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا إِلَى جَنْبِ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏فِي الْمَسْجِدِ فَمَرَّ شَيْخٌ جَمِيلٌ مِنْ ‏ ‏بَنِي غِفَارٍ ‏ ‏وَفِي أُذُنَيْهِ صَمَمٌ ‏ ‏أَوْ قَالَ وَقْرٌ أَرْسَلَ إِلَيْهِ ‏ ‏حُمَيْدٌ ‏ ‏فَلَمَّا أَقْبَلَ قَالَ يَا ابْنَ أَخِي أَوْسِعْ لَهُ فِيمَا بَيْنِي وَبَيْنَكَ فَإِنَّهُ قَدْ صَحِبَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَ حَتَّى جَلَسَ فِيمَا بَيْنِي وَبَيْنَهُ فَقَالَ لَهُ ‏ ‏حُمَيْدٌ ‏ ‏هَذَا الْحَدِيثُ الَّذِي حَدَّثْتَنِي عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏الشَّيْخُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يُنْشِئُ السَّحَابَ فَيَنْطِقُ أَحْسَنَ الْمَنْطِقِ وَيَضْحَكُ أَحْسَنَ الضَّحِكِ ‏","","",""],[22575,22575,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَعْدٍ ‏ ‏عَنِ ‏ ‏الصُّنَابِحِيِّ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْغُلُوطَاتِ ‏ ‏قَالَ ‏ ‏الْأَوْزَاعِّيُّ ‏ ‏الْغُلُوطَاتِ ‏ ‏شِدَادُ الْمَسَائِلِ وَصِعَابُهَا ‏","","",""],[22576,22576,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِىُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَعْدٍ ‏ ‏عَنِ ‏ ‏الصُّنَابِحِيِّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ ‏ ‏الْغُلُوطَاتِ ‏","","",""],[22577,22577,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي عُفَيْرٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سَهْلِ بْنِ أَبِي حَثْمَةَ ‏ ‏عَنْ ‏ ‏مُحَيِّصَةَ بْنِ مَسْعُودٍ الْأَنْصَارِيِّ ‏ ‏أَنَّهُ ‏ ‏كَانَ لَهُ غُلَامٌ حَجَّامٌ يُقَالُ لَهُ ‏ ‏نَافِعٌ أَبُو طَيِّبَةَ ‏ ‏فَانْطَلَقَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْأَلُهُ عَنْ ‏ ‏خَرَاجِهِ ‏ ‏فَقَالَ لَا تَقْرَبْهُ فَرَدَّهُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏اعْلِفْ بِهِ ‏ ‏النَّاضِحَ ‏ ‏وَاجْعَلْهُ فِي كِرْشِهِ ‏","","",""],[22578,22578,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ مُحَيِّصَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏اسْتَأْذَنَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي إِجَارَةِ ‏ ‏الْحَجَّامِ ‏ ‏فَنَهَاهُ عَنْهَا فَلَمْ يَسْأَلْهُ فِيهَا حَتَّى قَالَ لَهُ ‏ ‏اعْلِفْهُ نَاضِحَكَ وَأَطْعِمْهُ رَقِيقَكَ ‏","","",""],[22579,22579,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ هُوَ ابْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حَرامِ بْنِ مُحَيِّصَةَ ‏ ‏أَنَّ نَاقَةً ‏ ‏لِلْبَرَاءِ ‏ ‏دَخَلَتْ حَائِطًا فَأَفْسَدَتْ فِيهِ ‏ ‏فَقَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ عَلَى أَهْلِ الْحَوَائِطِ حِفْظَهَا بِالنَّهَارِ وَأَنَّ مَا أَفْسَدَتْ الْمَوَاشِي بِاللَّيْلِ ضَامِنٌ عَلَى أَهْلِهَا ‏","","",""],[22580,22580,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حَرَامِ بْنِ سَاعِدَةَ بْنِ مُحَيِّصَةَ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كَانَ لَهُ غُلَامٌ حَجَّامٌ يُقَالُ لَهُ ‏ ‏أَبُو طَيِّبَةَ ‏ ‏يَكْسِبُ كَسْبًا كَثِيرًا فَلَمَّا نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ كَسْبِ الْحَجَّامِ اسْتَرْخَصَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِ فَأَبَى عَلَيْهِ فَلَمْ يَزَلْ يُكَلِّمُهُ فِيهِ وَيَذْكُرُ لَهُ الْحَاجَةَ حَتَّى قَالَ لَهُ ‏ ‏لِتُلْقِ كَسْبَهُ فِي بَطْنِ ‏ ‏نَاضِحِكَ ‏","","",""],[22581,22581,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حَرَامِ بْنِ سَعْدِ بْنِ مُحَيِّصَةَ ‏ ‏أَنَّ ‏ ‏مُحَيِّصَةَ ‏ ‏سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ كَسْبِ حَجَّامٍ لَهُ فَنَهَاهُ عَنْهُ فَلَمْ يَزَلْ بِهِ يُكَلِّمُهُ حَتَّى قَالَ ‏ ‏اعْلِفْهُ ‏ ‏نَاضِحَكَ ‏ ‏وَأَطْعِمْهُ رَقِيقَكَ ‏","","",""],[22582,22582,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ وَسَمِعَهُ ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏وَحَرَامِ بْنِ سَعْدِ بْنِ مُحَيِّصَةَ ‏ ‏أَنَّ نَاقَةً ‏ ‏لِلْبَرَاءِ بْنِ عَازِبٍ ‏ ‏دَخَلَتْ حَائِطَ قَوْمٍ فَأَفْسَدَتْ ‏ ‏فَقَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِحِفْظِ الْأَمْوَالِ عَلَى أَهْلِهَا بِالنَّهَارِ وَأَنَّ عَلَى أَهْلِ الْمَاشِيَةِ مَا أَصَابَتْ بِاللَّيْلِ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حَرَامِ بْنِ سَاعِدَةَ بْنِ مُحَيِّصَةَ بْنِ مَسْعُودٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏مُحَيِّصَةَ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كَانَ لَهُ غُلَامٌ حَجَّامٌ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[22583,22583,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حَرَامِ بْنِ مُحَيِّصَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ كَسْبِ الْحَجَّامِ فَنَهَاهُ فَأَعَادَ عَلَيْهِ فَنَهَاهُ فَذَكَرَ مِنْ حَاجَتِهِ فَقَالَ ‏ ‏اعْلِفْ ‏ ‏نَاضِحَكَ ‏ ‏وَأَطْعِمْهُ رَقِيقَكَ ‏","","",""],[22584,22584,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حَرَامِ بْنِ مُحَيِّصَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ نَاقَةً ‏ ‏لِلْبَرَاءِ بْنِ عَازِبٍ ‏ ‏دَخَلَتْ حَائِطَ رَجُلٍ فَأَفْسَدَتْهُ ‏ ‏فَقَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى أَهْلِ الْأَمْوَالِ حِفْظَهَا بِالنَّهَارِ وَعَلَى أَهْلِ الْمَوَاشِي حِفْظَهَا بِاللَّيْلِ ‏","","",""],[22585,22585,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حَرَامِ بْنِ مُحَيِّصَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ كَسْبِ الْحَجَّامِ فَنَهَاهُ عَنْهُ فَذَكَرَ لَهُ الْحَاجَةَ فَقَالَ اعْلِفْهُ نَوَاضِحَكَ ‏","","",""],[22586,22586,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَيُّوبَ ‏ ‏أَنَّ رَجُلًا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏حَدَّثَهُ يُقَالُ لَهُ ‏ ‏مُحَيِّصَةُ ‏ ‏كَانَ لَهُ غُلَامٌ حَجَّامٌ فَزَجَرَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ كَسْبِهِ فَقَالَ أَفَلَا أُطْعِمُهُ يَتَامَى لِي قَالَ لَا قَالَ أَفَلَا أَتَصَدَّقُ بِهِ قَالَ لَا ‏ ‏فَرَخَّصَ لَهُ أَنْ يَعْلِفَهُ ‏ ‏نَاضِحَهُ ‏","","",""],[22587,22587,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ صَخْرٍ الْبَيَاضِيِّ ‏ ‏قَالَ ‏ ‏كُنْتُ امْرَأً أُصِيبُ مِنْ النِّسَاءِ مَا لَا يُصِيبُ غَيْرِي قَالَ فَلَمَّا دَخَلَ شَهْرُ رَمَضَانَ خِفْتُ ‏ ‏فَتَظَاهَرْتُ ‏ ‏مِنْ امْرَأَتِي فِي الشَّهْرِ قَالَ فَبَيْنَمَا هِيَ تَخْدُمُنِي ذَاتَ لَيْلَةٍ إِذْ تَكَشَّفَ لِي مِنْهَا شَيْءٌ فَلَمْ أَلْبَثْ أَنْ وَقَعْتُ عَلَيْهَا فَأَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرْتُهُ فَقَالَ ‏ ‏حَرِّرْ رَقَبَةً قَالَ قُلْتُ وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا أَمْلِكُ رَقَبَةً غَيْرَ رَقَبَتِي قَالَ فَصُمْ شَهْرَيْنِ مُتَتَابِعَيْنِ فَقُلْتُ وَهَلْ أَصَابَنِي الَّذِي أَصَابَنِي إِلَّا مِنْ الصِّيَامِ قَالَ فَأَطْعِمْ سِتِّينَ مِسْكِينًا ‏","","",""],[22588,22588,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏رِفَاعَةَ بْنِ شَدَّادٍ ‏ ‏قَالَ ‏ ‏كُنْتُ ‏ ‏أَقُومُ عَلَى رَأْسِ ‏ ‏الْمُخْتَارِ ‏ ‏فَلَمَّا تَبَيَّنَتْ لِي كِذَابَتُهُ هَمَمْتُ أَيْمُ اللَّهِ أَنْ أَسُلَّ سَيْفِي فَأَضْرِبَ عُنُقَهُ حَتَّى تَذَكَّرْتُ حَدِيثًا حَدَّثَنِيهِ ‏ ‏عَمْرُو بْنُ الْحَمِقِ ‏ ‏قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ آمَنَ رَجُلًا عَلَى نَفْسِهِ فَقَتَلَهُ أُعْطِيَ لِوَاءَ الْغَدْرِ يَوْمَ الْقِيَامَةِ ‏","","",""],[22589,22589,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى الْقَارِئُ أَبُو عُمَرَ ‏ ‏حَدَّثَنِي ‏ ‏السَّدِيُّ ‏ ‏عَنْ ‏ ‏رِفَاعَةَ الْقِتْبَانِيِّ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏الْمُخْتَارِ ‏ ‏قَالَ فَأَلْقَى لِي وِسَادَةً وَقَالَ لَوْلَا أَنَّ أَخِي ‏ ‏جِبْرِيلَ ‏ ‏قَامَ عَنْ هَذِهِ لَأَلْقَيْتُهَا لَكَ قَالَ فَأَرَدْتُ أَنْ أَضْرِبَ عُنُقَهُ فَذَكَرْتُ حَدِيثًا حَدَّثَنِي بِهِ أَخِي ‏ ‏عَمْرُو بْنُ الْحَمِقِ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّمَا مُؤْمَنٍ أَمَّنَ مُؤْمِنًا عَلَى دَمِهِ فَقَتَلَهُ فَأَنَا مِنْ الْقَاتِلِ بَرِيءٌ ‏","","",""],[22590,22590,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ ‏ ‏قَالَ ‏ ‏قَالَ بَعْضُ الْمُشْرِكِينَ وَهُمْ يَسْتَهْزِئُونَ بِهِ إِنِّي لَأَرَى صَاحِبَكُمْ يُعَلِّمُكُمْ حَتَّى الْخِرَاءَةِ قَالَ ‏ ‏سَلْمَانُ ‏ ‏أَجَلْ أَمَرَنَا أَنْ ‏ ‏لَا نَسْتَقْبِلَ الْقِبْلَةَ وَلَا نَسْتَنْجِيَ بِأَيْمَانِنَا وَلَا نَكْتَفِيَ بِدُونِ ثَلَاثَةِ أَحْجَارٍ لَيْسَ فِيهَا ‏ ‏رَجِيعٌ ‏ ‏وَلَا عَظْمٌ ‏","","",""],[22591,22591,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عُبَيْدٍ الْمُكْتِبِ ‏ ‏عَنْ ‏ ‏أَبِي الطُّفَيْلِ ‏ ‏عَنْ ‏ ‏سَلْمَانَ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْبَلُ الْهَدِيَّةَ وَلَا يَقْبَلُ الصَّدَقَةَ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏و حَدَّثَنَاه ‏ ‏عَلِيُّ بْنُ حَكِيمٍ ‏ ‏أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عُبَيْدٍ الْمُكْتِبِ ‏ ‏بِإِسْنَادِهِ ‏ ‏نَحْوَهُ ‏","","",""],[22592,22592,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏رَجُلٌ ‏ ‏مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ إِنِّي لَأَرَى صَاحِبَكُمْ يُعَلِّمُكُمْ كَيْفَ تَصْنَعُونَ حَتَّى إِنَّهُ لَيُعَلِّمُكُمْ إِذَا أَتَى أَحَدُكُمْ ‏ ‏الْغَائِطَ ‏ ‏قَالَ قُلْتُ نَعَمْ أَجَلْ وَلَوْ سَخِرْتَ إِنَّهُ لَيُعَلِّمُنَا كَيْفَ يَأْتِي أَحَدُنَا ‏ ‏الْغَائِطَ ‏ ‏وَإِنَّهُ ‏ ‏يَنْهَانَا أَنْ يَسْتَقْبِلَ أَحَدُنَا الْقِبْلَةَ وَأَنْ يَسْتَدْبِرَهَا وَأَنْ ‏ ‏يَسْتَنْجِيَ ‏ ‏أَحَدُنَا بِيَمِينِهِ وَأَنْ ‏ ‏يَتَمَسَّحَ ‏ ‏أَحَدُنَا ‏ ‏بِرَجِيعٍ ‏ ‏وَلَا عَظْمٍ وَأَنْ ‏ ‏يَسْتَنْجِيَ ‏ ‏بِأَقَلَّ مِنْ ثَلَاثَةِ أَحْجَارٍ ‏","","",""],[22593,22593,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ قَيْسٍ الْمَاصِرُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي قُرَّةَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏حُذَيْفَةُ ‏ ‏بِالْمَدَائِنِ ‏ ‏فَكَانَ يَذْكُرُ أَشْيَاءَ قَالَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَ ‏ ‏حُذَيْفَةُ ‏ ‏إِلَى ‏ ‏سَلْمَانَ ‏ ‏فَيَقُولُ ‏ ‏سَلْمَانُ ‏ ‏يَا ‏ ‏حُذَيْفَةُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَغْضَبُ فَيَقُولُ ‏ ‏وَيَرْضَى وَيَقُولُ لَقَدْ عَلِمْتُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطَبَ فَقَالَ ‏ ‏أَيُّمَا رَجُلٍ مِنْ أُمَّتِي سَبَبْتُهُ سَبَّةً فِي غَضَبِي أَوْ لَعَنْتُهُ لَعْنَةً فَإِنَّمَا أَنَا مِنْ وَلَدِ ‏ ‏آدَمَ ‏ ‏أَغْضَبُ كَمَا يَغْضَبُونَ وَإِنَّمَا بَعَثَنِي رَحْمَةً لِلْعَالَمِينَ فَاجْعَلْهَا صَلَاةً عَلَيْهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[22594,22594,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ ‏ ‏سَلْمَانَ الْفَارِسِيِّ ‏ ‏تَحْتَ شَجَرَةٍ وَأَخَذَ مِنْهَا غُصْنًا يَابِسًا فَهَزَّهُ حَتَّى ‏ ‏تَحَاتَّ ‏ ‏وَرَقُهُ ثُمَّ قَالَ يَا ‏ ‏أَبَا عُثْمَانَ ‏ ‏أَلَا تَسْأَلُنِي لِمَ أَفْعَلُ هَذَا قُلْتُ وَلِمَ تَفْعَلُهُ فَقَالَ هَكَذَا فَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا مَعَهُ تَحْتَ شَجَرَةٍ فَأَخَذَ مِنْهَا غُصْنًا يَابِسًا فَهَزَّهُ حَتَّى ‏ ‏تَحَاتَّ ‏ ‏وَرَقُهُ فَقَالَ يَا ‏ ‏سَلْمَانُ ‏ ‏أَلَا تَسْأَلُنِي لِمَ أَفْعَلُ هَذَا فَقُلْتُ وَلِمَ تَفْعَلُهُ قَالَ ‏ ‏إِنَّ الْمُسْلِمَ إِذَا تَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ ثُمَّ صَلَّى الصَّلَوَاتِ الْخَمْسَ ‏ ‏تَحَاتَّتْ ‏ ‏خَطَايَاهُ كَمَا ‏ ‏يَتَحَاتُّ ‏ ‏هَذَا الْوَرَقُ وَقَالَ ‏ { ‏وَأَقِمْ الصَّلَاةَ طَرَفَيْ النَّهَارِ وَزُلَفًا مِنْ اللَّيْلِ إِنَّ الْحَسَنَاتِ يُذْهِبْنَ السَّيِّئَاتِ ذَلِكَ ذِكْرَى لِلذَّاكِرِينَ ‏}","","",""],[22595,22595,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏وَالْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ الْفَارِسِيِّ ‏ ‏قَالَ ‏ ‏قَالَ لَهُ الْمُشْرِكُونَ إِنَّا نَرَى صَاحِبَكُمْ يُعَلِّمُكُمْ حَتَّى يُعَلِّمَكُمْ ‏ ‏الْخِرَاءَةَ ‏ ‏قَالَ أَجَلْ إِنَّهُ ‏ ‏يَنْهَانَا أَنْ ‏ ‏يَسْتَنْجِيَ ‏ ‏أَحَدُنَا بِيَمِينِهِ أَوْ يَسْتَقْبِلَ الْقِبْلَةَ وَيَنْهَانَا عَنْ ‏ ‏الرَّوْثِ ‏ ‏وَالْعِظَامِ وَقَالَ لَا ‏ ‏يَسْتَنْجِي ‏ ‏أَحَدُكُمْ بِدُونِ ثَلَاثَةِ أَحْجَارٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏أَنَّ رَجُلًا مِنْ الْمُشْرِكِينَ قَالَ لِرَجُلٍ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَّمَكُمْ هَذَا كُلَّ شَيْءٍ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[22596,22596,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ وَدِيعَةَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ الْخَيْرِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا يَغْتَسِلُ رَجُلٌ يَوْمَ الْجُمُعَةِ وَيَتَطَهَّرُ بِمَا اسْتَطَاعَ مِنْ طُهْرٍ وَيَدَّهِنُ مِنْ دُهْنِهِ أَوْ ‏ ‏يَمَسُّ ‏ ‏مِنْ طِيبِ بَيْتِهِ ثُمَّ يَرُوحُ إِلَى الْمَسْجِدِ فَلَا يُفَرِّقُ بَيْنَ اثْنَيْنِ ثُمَّ ‏ ‏يُصَلِّي مَا كَتَبَ اللَّهُ لَهُ ثُمَّ يُنْصِتُ لِلْإِمَامِ إِذَا تَكَلَّمَ إِلَّا غُفِرَ لَهُ مَا بَيْنَهُ وَبَيْنَ الْجُمُعَةِ الْأُخْرَى ‏","","",""],[22597,22597,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏لَمَّا احْتُضِرَ ‏ ‏سَلْمَانُ ‏ ‏بَكَى وَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَهِدَ إِلَيْنَا عَهْدًا فَتَرَكْنَا مَا عَهِدَ إِلَيْنَا ‏ ‏أَنْ يَكُونَ ‏ ‏بُلْغَةُ ‏ ‏أَحَدِنَا مِنْ الدُّنْيَا كَزَادِ الرَّاكِبِ قَالَ ثُمَّ نَظَرْنَا فِيمَا تَرَكَ فَإِذَا قِيمَةُ مَا تَرَكَ بِضْعَةٌ وَعِشْرُونَ دِرْهَمًا أَوْ بِضْعَةٌ وَثَلَاثُونَ دِرْهَمًا ‏","","",""],[22598,22598,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي قُرَّةَ الْكِنْدِيِّ ‏ ‏عَنْ ‏ ‏سَلْمَانَ الْفَارِسِيِّ ‏ ‏قَالَ ‏ ‏كُنْتُ مِنْ أَبْنَاءِ ‏ ‏أَسَاوِرَةِ ‏ ‏فَارِسَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏قَالَ فَانْطَلَقْتُ تَرْفَعُنِي أَرْضٌ وَتَخْفِضُنِي أُخْرَى حَتَّى مَرَرْتُ عَلَى قَوْمٍ مِنْ ‏ ‏الْأَعْرَابِ ‏ ‏فَاسْتَعْبَدُونِي فَبَاعُونِي حَتَّى اشْتَرَتْنِي امْرَأَةٌ فَسَمِعْتُهُمْ يَذْكُرُونَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَ الْعَيْشُ عَزِيزًا فَقُلْتُ لَهَا هَبِي لِي يَوْمًا فَقَالَتْ نَعَمْ فَانْطَلَقْتُ فَاحْتَطَبْتُ حَطَبًا فَبِعْتُهُ فَصَنَعْتُ طَعَامًا فَأَتَيْتُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَضَعْتُهُ بَيْنَ يَدَيْهِ فَقَالَ مَا هَذَا فَقُلْتُ صَدَقَةٌ فَقَالَ لِأَصْحَابِهِ ‏ ‏كُلُوا وَلَمْ يَأْكُلْ قُلْتُ هَذِهِ مِنْ عَلَامَاتِهِ ثُمَّ مَكَثْتُ مَا شَاءَ اللَّهُ أَنْ أَمْكُثَ فَقُلْتُ لِمَوْلَاتِي هَبِي لِي يَوْمًا قَالَتْ نَعَمْ فَانْطَلَقْتُ فَاحْتَطَبْتُ حَطَبًا بِأَكْثَرَ مِنْ ذَلِكَ فَصَنَعْتُ طَعَامًا فَأَتَيْتُهُ بِهِ وَهُوَ جَالِسٌ بَيْنَ أَصْحَابِهِ فَوَضَعْتُهُ بَيْنَ يَدَيْهِ فَقَالَ مَا هَذَا قُلْتُ هَدِيَّةٌ فَوَضَعَ يَدَهُ وَقَالَ لِأَصْحَابِهِ خُذُوا بِسْمِ اللَّهِ وَقُمْتُ خَلْفَهُ فَوَضَعَ رِدَاءَهُ فَإِذَا خَاتَمُ النُّبُوَّةِ فَقُلْتُ أَشْهَدُ أَنَّكَ رَسُولُ اللَّهِ فَقَالَ وَمَا ذَاكَ فَحَدَّثْتُهُ عَنْ الرَّجُلِ وَقُلْتُ أَيَدْخُلُ الْجَنَّةَ يَا رَسُولَ اللَّهِ فَإِنَّهُ حَدَّثَنِي أَنَّكَ نَبِيٌّ فَقَالَ لَنْ يَدْخُلَ الْجَنَّةَ إِلَّا نَفْسٌ مُسْلِمَةٌ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّهُ أَخْبَرَنِي أَنَّكَ نَبِيٌّ أَيَدْخُلُ الْجَنَّةَ قَالَ لَنْ يَدْخُلَ الْجَنَّةَ إِلَّا نَفْسٌ مُسْلِمَةٌ ‏","","",""],[22599,22599,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ ‏ ‏قَالَ ‏ ‏قَالَ الْمُشْرِكُونَ إِنَّ هَذَا لَيُعَلِّمُكُمْ حَتَّى إِنَّهُ لَيُعَلِّمُكُمْ ‏ ‏الْخِرَاءَةَ ‏ ‏قَالَ قُلْتُ لَئِنْ قُلْتُمْ ذَاكَ لَقَدْ ‏ ‏نَهَانَا أَنْ نَسْتَقْبِلَ الْقِبْلَةَ أَوْ نَسْتَدْبِرَهَا أَوْ ‏ ‏نَسْتَنْجِيَ ‏ ‏بِأَيْمَانِنَا أَوْ يَكْتَفِيَ أَحَدُنَا بِدُونِ ثَلَاثَةِ أَحْجَارٍ أَوْ ‏ ‏يَسْتَنْجِيَ ‏ ‏أَحَدُنَا ‏ ‏بِرَجِيعٍ ‏ ‏أَوْ عَظْمٍ ‏","","",""],[22600,22600,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ لَيَسْتَحِي أَنْ يَبْسُطَ الْعَبْدُ إِلَيْهِ يَدَيْهِ ‏ ‏يَسْأَلُهُ خَيْرًا ‏ ‏فَيَرُدَّهُمَا خَائِبَتَيْنِ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏رَجُلٌ ‏ ‏فِي مَجْلِسِ ‏ ‏عَمْرِو بْنِ عُبَيْدٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا عُثْمَانَ ‏ ‏يُحَدِّثُ ‏ ‏بِهَذَا ‏ ‏عَنْ ‏ ‏سَلْمَانَ الْفَارِسِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏سَمُّوهُ لِي قَالُوا هُوَ ‏ ‏جَعْفَرُ بْنُ مَيْمُونٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏يَعْنِي ‏ ‏جَعْفَرَ ‏ ‏صَاحِبَ الْأَنْمَاطِ ‏","","",""]];
